        fixed_supply(
            f.choices,
            TEST_METADATA,
            supply,
            secret,
            ACCOUNT,
            f.output_root,
            TEST_SEED,
            f.native_inputs,
            f.replay_ids,
            f.owners,
            f.secrets,
            f.amounts,
