// PCASH Poseidon hashing.
//
// Every `poseidon(x_1..x_N)` in the spec is the length-tagged Poseidon2
// sponge over the BN254 t=4 (rf=8, rp=56) permutation:
//
//   state init = [0, 0, 0, (N as Field) * 2^64]
//   rate-3 absorb into lanes 0..2, permute per chunk
//   return lane 0
//   N == 0 => one permutation
//
// The vendored `poseidon::poseidon2::Poseidon2::hash(input, N)` implements
// this construction. The known answers below pin representative outputs to
// the Rust/TS vectors.

use poseidon::poseidon2::Poseidon2;

/// Length-tagged Poseidon2 sponge over N field elements.
pub fn pcash_hash<let N: u32>(input: [Field; N]) -> Field {
    Poseidon2::hash(input, N)
}

mod tests {
    use super::pcash_hash;

    // Golden values from vectors/poseidon2_vectors.json cover empty input and
    // both sides of a rate-3 chunk boundary.
    #[test]
    fn test_poseidon_agreement_gate() {
        let empty: [Field; 0] = [];
        assert(
            pcash_hash(empty) == 0x18dfb8dc9b82229cff974efefc8df78b1ce96d9d844236b496785c698bc6732e,
            "poseidon([]) must match the published vector",
        );

        assert(
            pcash_hash([1]) == 0x168758332d5b3e2d13be8048c8011b454590e06c44bce7f702f09103eef5a373,
            "poseidon([1]) must match the published vector",
        );

        assert(
            pcash_hash([1, 2])
                == 0x038682aa1cb5ae4e0a3f13da432a95c77c5c111f6f030faf9cad641ce1ed7383,
            "poseidon([1,2]) must match the published vector",
        );

        // Boundary case: exactly one full rate-3 chunk (no final extra permutation).
        assert(
            pcash_hash([1, 2, 3])
                == 0x23864adb160dddf590f1d3303683ebcb914f828e2635f6e85a32f0a1aecd3dd8,
            "poseidon([1,2,3]) must match the published vector",
        );

        // Two chunks: one full + a 1-element remainder.
        assert(
            pcash_hash([1, 2, 3, 4])
                == 0x130bf204a32cac1f0ace56c78b731aa3809f06df2731ebcf6b3464a15788b1b9,
            "poseidon([1,2,3,4]) must match the published vector",
        );
    }
}

// PCASH structural parameters (tree depths and range-check bit widths). Domain tags live in `pcash_constants` (generated); these are hand
// maintained protocol constants used by L1 derivation and transaction relations.

// --- Merkle tree depths ---
// The output-commitment tree and the account-state tree are indexed by a 40-bit
// position.
pub global MERKLE_DEPTH: u32 = 40;
// The account-rule-set commitment is a depth-8 sparse root over active
// account-rule-entry commitments.
pub global ACCOUNT_RULE_SET_DEPTH: u32 = 8;
// Typed block-header and state commitments are depth-4 sparse Poseidon trees.
pub global BLOCK_HEADER_TREE_DEPTH: u32 = 4;
pub global STATE_TREE_DEPTH: u32 = 4;
// The L1 origin tree and the PCASH history tree are depth-40 append-only trees.
pub global L1_ORIGIN_TREE_DEPTH: u32 = 40;
pub global HISTORY_TREE_DEPTH: u32 = 40;
// Each L1 origin leaf commits its block's normalized logs in a depth-64 tree.
pub global L1_LOG_TREE_DEPTH: u32 = 64;

// --- Range-check bit widths ---
pub global ADDRESS_BITS: u32 = 160; // uint160(address) inputs
pub global AMOUNT_BITS: u32 = 128; // note amounts and fees
// The largest initial supply of a standard fungible asset: five maximal notes.
pub global MAX_ASSET_SUPPLY: Field = 5 * 0xffffffffffffffffffffffffffffffff;
// The width of MAX_ASSET_SUPPLY, which bounds every asset aggregate: an initial
// supply and a burn amount.
pub global ASSET_AGGREGATE_BITS: u32 = 131;
pub global VALID_UNTIL_BITS: u32 = 64; // transaction timestamps
// The uint64 block number, timestamp, and log count of an L1 origin leaf.
pub global L1_ORIGIN_INTEGER_BITS: u32 = 64;

// PCASH range checks.

use crate::primitives::params::{ADDRESS_BITS, AMOUNT_BITS, ASSET_AGGREGATE_BITS, VALID_UNTIL_BITS};

pub fn assert_address(x: Field) {
    x.assert_max_bit_size::<ADDRESS_BITS>();
}

pub fn assert_amount(x: Field) {
    x.assert_max_bit_size::<AMOUNT_BITS>();
}

pub fn assert_asset_aggregate(x: Field) {
    x.assert_max_bit_size::<ASSET_AGGREGATE_BITS>();
}

// A 64-bit timestamp: a validity bound, where a zero not-before bound is
// unconstrained, or a deadline.
pub fn assert_timestamp(x: Field) {
    x.assert_max_bit_size::<VALID_UNTIL_BITS>();
}

// `a <= b` for two timestamps, each range-checked to the timestamp width.
pub fn timestamp_le(a: Field, b: Field) -> bool {
    assert_timestamp(a);
    assert_timestamp(b);
    (a as u64) <= (b as u64)
}

mod tests {
    use crate::primitives::params::ASSET_AGGREGATE_BITS;
    use super::{
        assert_address, assert_amount, assert_asset_aggregate, assert_timestamp, timestamp_le,
    };

    #[test]
    fn test_range_helpers_accept_in_range() {
        assert_address(0xffffffffffffffffffffffffffffffffffffffff); // 2^160 - 1
        assert_amount(0xffffffffffffffffffffffffffffffff); // 2^128 - 1
        assert_asset_aggregate((2 as Field).pow_32(ASSET_AGGREGATE_BITS as Field) - 1);
        assert_timestamp(0xffffffffffffffff); // 2^64 - 1
    }

    #[test(should_fail)]
    fn test_amount_rejects_2_to_128() {
        assert_amount(0x100000000000000000000000000000000);
    }

    #[test(should_fail)]
    fn test_asset_aggregate_rejects_aggregate_limit() {
        assert_asset_aggregate((2 as Field).pow_32(ASSET_AGGREGATE_BITS as Field));
    }

    #[test(should_fail)]
    fn test_address_rejects_2_to_160() {
        assert_address(0x10000000000000000000000000000000000000000);
    }

    #[test(should_fail)]
    fn test_timestamp_rejects_2_to_64() {
        assert_timestamp(0x10000000000000000);
    }

    #[test]
    fn test_timestamp_le_compares_in_range_values() {
        assert(timestamp_le(100, 200));
        assert(timestamp_le(200, 200));
        assert(!timestamp_le(201, 200));
        assert(timestamp_le(0xffffffffffffffff, 0xffffffffffffffff));
    }

    #[test(should_fail)]
    fn test_timestamp_le_rejects_a_value_above_the_timestamp_width() {
        let _ = timestamp_le(0, 0x10000000000000000);
    }

    #[test(should_fail)]
    fn test_amount_rejects_negative_field_representative() {
        assert_amount(-1);
    }
}

