            TEST_RECENT_BLOCK,
            TEST_CONFIGURATION,
            Signature { signature: SIGNED_BATCH_SIGNATURE },
            TEST_SIGNING_KEY,
            TEST_NK_ROOT,
            0,
            outputs,
            0,
            0,
            0,
            tx,
            0,
            secrets,
