            TEST_PCASH_CHAIN_ID,
            TEST_RECENT_BLOCK,
            TEST_CONFIGURATION,
            TEST_SIGNER,
            TEST_NK_ROOT,
            0,
            outputs,
            25,
            relay_owner,
            tx,
            secrets,
            changes,
            no_namespace_opening(),
            0,
        )
    }

