// The reference rules' configuration: the EIP-712 domain separator the owner
// signs under and the account's nullifier key commitment.
//
//   configurationCommitment = poseidon(REFERENCE_CONFIGURATION_DOMAIN,
//                                      domainSeparatorHigh128, domainSeparatorLow128,
//                                      nullifierKeyCommitment)
//
// A rule verifies every signature under the committed separator. The signer is
// not configured: the rule derives its address from the signing key. The rule
// opens the nullifier key commitment with the `nk_root` it derives owner change
// and self-issuance secrets from, so the installing wallet fixes that root.

use crate::generated::reference_rule_constants::REFERENCE_CONFIGURATION_DOMAIN;
use pcash_protocol::primitives::hash::pcash_hash;
use signature_common::eip712::{domain_separator, flat_message_signing_hash};

pub struct Configuration {
    pub domain_separator_high: Field,
    pub domain_separator_low: Field,
}

impl Configuration {
    // The EIP-712 signing hash of a flat message under the committed separator.
    pub fn signing_hash<let N: u32>(self, type_hash: [u8; 32], fields: [Field; N]) -> [u8; 32] {
        flat_message_signing_hash(
            domain_separator(self.domain_separator_high, self.domain_separator_low),
            type_hash,
            fields,
        )
    }
}

pub fn configuration_commitment(
    configuration: Configuration,
    nullifier_key_commitment: Field,
) -> Field {
    pcash_hash([
        REFERENCE_CONFIGURATION_DOMAIN,
        configuration.domain_separator_high,
        configuration.domain_separator_low,
        nullifier_key_commitment,
    ])
}

// Contract-targeted fee sponsorship rule of the reference user account.
//
// A User Account sponsor approves one open fee or private relay payment for a
// named Contract Account. The message names the contract, payout terms,
// transaction context, and validity window. The signed transaction context
// fixes every nullifier, including the primary's, so the signature can fund
// only the one transaction that spends exactly those inputs.
//
// The sponsored-transfer kernel enforces the rest — that the sponsor owns every
// native input, that the primary owns every asset and application input, and
// that native value leaves only as the open fee, one relay note, and change to
// the sponsor. This rule binds what the sponsor saw and requires every native
// output other than the signed relay note to be owner change under the
// sponsor's derived secret.

use crate::configuration::Configuration;
use crate::message::verify_value_message;
use crate::owner::open_owner;
use crate::value_rule::assert_native_fee_outputs;
use pcash_protocol::authorization::statement::{
    contract_fee_sponsorship_action_commitment, rule_statement, RULE_STATEMENT_LENGTH,
};
use pcash_protocol::ledger::private_value::{private_value_commitment, PrivateValue};
use signature_common::secp256k1::{Secp256k1PubKey, Signature};

// keccak256 of the SDK CONTRACT_FEE_SPONSORSHIP_EIP712_TYPE, written by scripts/circuits/gen_reference_message_types.mjs.
global CONTRACT_FEE_SPONSORSHIP_TYPE_HASH: [u8; 32] = [
    0x63, 0x94, 0xbb, 0xbe, 0x8f, 0xc8, 0xa8, 0xfe, 0xa9, 0xe4, 0x53, 0x93, 0xf5, 0xa8, 0xe0, 0xdc,
    0xd0, 0xfb, 0xef, 0xf7, 0x99, 0x4c, 0xb7, 0x12, 0xa3, 0x11, 0xb9, 0x5b, 0x18, 0x4a, 0x55, 0x7b,
];

pub fn contract_fee_sponsorship_relation<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    configuration: Configuration,
    signer_address: Field,
    nk_root: Field,
    sponsored_contract: Field,
    relay_fee_amount: Field,
    relay_fee_owner_commitment: Field,
    native_change_amount: Field,
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    event_entry: Field,
) -> [Field; RULE_STATEMENT_LENGTH] {
    let owner = open_owner(signer_address, nk_root, configuration);
    assert_native_fee_outputs(
        private_value,
        signer_address,
        nk_root,
        relay_fee_amount,
        relay_fee_owner_commitment,
        native_change_amount,
    );
    // No open or bearer sponsorship: the kernel builds this action from the
    // contract it authenticated, or for a creation from the address the node
    // derives, so it matches only the signed contract.
    rule_statement(
        owner.authorization_commitment,
        contract_fee_sponsorship_action_commitment(
            pcash_chain_id,
            private_value_commitment(private_value),
            sponsored_contract,
        ),
        recent_pcash_block_hash,
        event_entry,
    )
}

pub fn authorize<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    configuration: Configuration,
    signature: Signature,
    pubkey: Secp256k1PubKey,
    nk_root: Field,
    sponsored_contract: Field,
    issuance_recipient: Field,
    relay_fee_amount: Field,
    relay_fee_owner_commitment: Field,
    native_change_amount: Field,
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    issuance_note_secret: Field,
    event_entry: Field,
) -> [Field; RULE_STATEMENT_LENGTH] {
    let signer_address = pubkey.ethereum_address();
    let statement = contract_fee_sponsorship_relation(
        pcash_chain_id,
        recent_pcash_block_hash,
        configuration,
        signer_address,
        nk_root,
        sponsored_contract,
        relay_fee_amount,
        relay_fee_owner_commitment,
        native_change_amount,
        private_value,
        event_entry,
    );
    verify_value_message(
        signature,
        pubkey,
        signer_address,
        configuration,
        CONTRACT_FEE_SPONSORSHIP_TYPE_HASH,
        pcash_chain_id,
        nk_root,
        [sponsored_contract],
        [],
        private_value,
        issuance_recipient,
        issuance_note_secret,
        relay_fee_amount,
        relay_fee_owner_commitment,
    );
    statement
}

