    fn with_marker(replay_id: Field) -> Fixture<4, 5> {
        let mut f = one_output();
        f.choices.input_slot_classes[1] = SLOT_CLASS_APPLICATION;
        f.replay_ids[1] = replay_id;
        f
    }

    // The marker is the creating account's, scoped to its selected rule entry,
    // exactly as in a transfer.
    #[test]
    fn test_fixed_supply_derives_the_application_marker_of_the_creating_account() {
        let value: PrivateValue<4, 5, 0> = run(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET);
        assert(value.nullifiers[1] == application_marker(ACCOUNT, 0x7e));
        assert(value.nullifiers[1] == application_nullifier(ACCOUNT.address, ACCOUNT.entry, 0x7e));
    }

    // A rule approved the private value with its marker; one built from
    // another replay ID is another private value, so the rule's statement does
    // not match it.
    #[test(should_fail_with = "rule statement must match the kernel's statement")]
    fn test_fixed_supply_rejects_a_marker_the_rule_did_not_approve() {
        let (_, approved, asset_id): (PrivateValue<4, 5, 0>, Field, Field) =
            build(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET);
        let (_, built, _): (PrivateValue<4, 5, 0>, Field, Field) =
            build(with_marker(0x7f), TEST_SUPPLY, TEST_SECRET);
        assert_rule_statement(
            [1, asset_creation_action_commitment(7, approved, asset_id), 2, 0],
            1,
            asset_creation_action_commitment(7, built, asset_id),
            2,
            0,
        );
    }

    #[test]
    fn test_fixed_supply_accepts_replay_id_zero() {
        let value: PrivateValue<4, 5, 0> = run(with_marker(0), TEST_SUPPLY, TEST_SECRET);
        assert(value.nullifiers[1] == application_marker(ACCOUNT, 0));
    }

    // One fact authorizes at most one asset creation per account and rule
    // entry: another asset secret creates another asset under the same
    // marker, which the node's nullifier uniqueness then rejects.
    #[test]
    fn test_fixed_supply_application_marker_is_the_same_for_another_asset() {
        let first: PrivateValue<4, 5, 0> = run(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET);
        let second: PrivateValue<4, 5, 0> = run(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET + 1);
        assert(first.nullifiers[0] != second.nullifiers[0]);
        assert(first.nullifiers[1] == second.nullifiers[1]);
    }

    #[test(should_fail_with = "asset burn amount must be zero")]
    fn test_fixed_supply_rejects_nonzero_burn() {
        let mut f = one_output();
        f.choices.asset_burn_amount = 1;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_underminting() {
        let _: PrivateValue<4, 5, 0> = run(
            fixture([TEST_SUPPLY - 1, 0, 0, 0, 0]),
            TEST_SUPPLY,
            TEST_SECRET,
        );
    }

    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_overminting() {
        let _: PrivateValue<4, 5, 0> = run(
            fixture([TEST_SUPPLY + 1, 0, 0, 0, 0]),
            TEST_SUPPLY,
            TEST_SECRET,
        );
    }

    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_no_asset_outputs() {
        let _: PrivateValue<4, 5, 0> = run(fixture([0; 5]), TEST_SUPPLY, TEST_SECRET);
    }

    // A zero supply creates the asset and its marker but no note.
    #[test]
    fn test_fixed_supply_accepts_a_zero_supply_without_asset_outputs() {
        let (value, _, asset_id): (PrivateValue<4, 5, 0>, Field, Field) =
            build(fixture([0; 5]), 0, TEST_SECRET);
        assert(asset_id == asset_id_of(0));
        assert(value.nullifiers[0] == asset_creation_marker(asset_id, TEST_SECRET));
        assert(value.output_slot_classes == [SLOT_CLASS_DUMMY; 5]);
    }

    // Real outputs are positive, so a zero supply cannot mint a unit.
    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_a_positive_asset_output_under_a_zero_supply() {
        let _: PrivateValue<4, 5, 0> = run(fixture([1, 0, 0, 0, 0]), 0, TEST_SECRET);
    }

    #[test(should_fail_with = "real output amount must be nonzero")]
    fn test_fixed_supply_rejects_zero_amount_asset_output() {
        let mut f = one_output();
        f.choices.output_slot_classes[1] = SLOT_CLASS_ASSET;
        f.owners[1] = TEST_OWNER;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail)]
    fn test_fixed_supply_rejects_asset_output_above_the_note_amount_range() {
        let supply = MAX_AMOUNT + 1;
        let _: PrivateValue<4, 5, 0> = run(fixture([supply, 0, 0, 0, 0]), supply, TEST_SECRET);
    }
}

// Shared S/L relation for a CONTRACT asset action sponsored by a USER account.
//
// The primary account moves the asset and owns every APPLICATION marker. A
// distinct fee-payer account contributes native PCASH for the open fee and
// optional private relay output, and receives at most one change note. Nothing
// else about the fee payer is at stake: their exposure is bounded by their own
// native contribution, and what the open fee and relay note leave returns to
// their address. The authorizing rule binds the relay note's amount and
// owner and which change opening it accepts — the reference rule requires the
// owner's derived change secret — because only that rule knows what the fee
// payer approved and which secrets they hold.
//
// The two authorizing accounts have fixed roles: the primary CONTRACT controls
// the asset action; the sponsoring USER funds the open fee or private relay
// output. This is not general multi-owner settlement. Private slot classes
// assign those roles without a per-slot owner field or a public sponsorship-mode
// indicator.
//
// This is a separate CHONK protocol kernel because it consumes two installed
// authorization applications rather than the transfer kernel's one.

use crate::authorization::account::{ACCOUNT_KIND_CONTRACT, ACCOUNT_KIND_USER};
use crate::authorization::authentication::{authenticate, AuthorizedAccount};
use crate::authorization::statement::{
    assert_rule_statement, contract_fee_sponsorship_action_commitment, RULE_STATEMENT_LENGTH,
    sponsored_transfer_action_commitment,
};
use crate::events::{EVENT_STATEMENT_LENGTH, events_commitment, verify_event};
use crate::ledger::fee_payment::{
    assert_native_fee_conservation, native_change_outputs, NativeChange, NativeRelayOutput,
};
use crate::ledger::opening::{open_transfer_inputs, open_value_state};
use crate::ledger::private_value::{
    PrivateValue, PrivateValueChoices, SLOT_CLASS_ASSET, transaction_statement,
};
use crate::ledger::section::{assert_asset_conservation, build_private_value, output_bodies};
use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, STATE_TREE_DEPTH};
use crate::primitives::types::InputNoteWitness;
use crate::recursion::{AppVerificationKey, verify_first_app, verify_next_app};

pub fn sponsored_transfer<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    choices: PrivateValueChoices<N_IN, N_OUT>,
    output_owner_commitments: [Field; N_OUT],
    output_dummy_secrets: [Field; N_OUT],
    asset_output_amounts: [Field; N_OUT],
    // The fee payer's change note, if any. Its secret is theirs to choose: the
    // change returns to a real party, not to a contract that later provers must
    // be able to reconstruct.
    native_change: NativeChange,
    native_relay_output: NativeRelayOutput,
    asset_id: Field,
    dummy_input_seed: Field,
    replay_ids: [Field; N_IN],
    block_header_state_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    output_root: Field,
    state_output_siblings: [Field; STATE_TREE_DEPTH],
    account_state_root: Field,
    state_account_siblings: [Field; STATE_TREE_DEPTH],
    primary: AuthorizedAccount,
    fee_payer: AuthorizedAccount,
    owner_inputs: [InputNoteWitness; N_IN],
    primary_statement: [Field; RULE_STATEMENT_LENGTH],
    primary_vk: AppVerificationKey,
    fee_statement: [Field; RULE_STATEMENT_LENGTH],
    fee_vk: AppVerificationKey,
    event_statement: [Field; EVENT_STATEMENT_LENGTH],
    event_application_vk: AppVerificationKey,
    event_salt: Field,
) -> [Field; N_IN + N_OUT + 9] {
    open_value_state(
        recent_pcash_block_hash,
        block_header_state_siblings,
        output_root,
        state_output_siblings,
        account_state_root,
        state_account_siblings,
    );

    // Targeted sponsorship only: a User Account pays the fee for a Contract
    // Account's action. User-to-user sponsorship is excluded from this relation.
    // Both kinds open under one canonical snapshot, which contains one account
    // per address. Their distinct kinds therefore also make their identities distinct.
    let primary_account = authenticate(
        primary,
        ACCOUNT_KIND_CONTRACT,
        primary_vk.hash,
        account_state_root,
    );
    let fee_account = authenticate(
        fee_payer,
        ACCOUNT_KIND_USER,
        fee_vk.hash,
        account_state_root,
    );

    let inputs = open_transfer_inputs(
        choices.input_slot_classes,
        primary_account,
        fee_account,
        output_root,
        asset_id,
        dummy_input_seed,
        owner_inputs,
        replay_ids,
    );
    assert(inputs.asset_amount != 0, "sponsored transfer must spend an asset input");
    assert(inputs.native_amount != 0, "sponsored transfer must spend a native input");

    // --- outputs ---------------------------------------------------------------
    // Native outputs are payer change and, optionally, one private relay note.
    // Asset outputs carry the witnessed asset amounts.
    let (owners, native_amounts) = native_change_outputs(
        choices.output_slot_classes,
        output_owner_commitments,
        fee_account.address,
        native_change,
        native_relay_output,
    );
    let mut output_amounts = native_amounts;
    for i in 0..N_OUT {
        if choices.output_slot_classes[i] == SLOT_CLASS_ASSET {
            output_amounts[i] = asset_output_amounts[i];
        }
    }
    let bodies = output_bodies(
        choices.output_slot_classes,
        asset_id,
        owners,
        output_dummy_secrets,
        output_amounts,
    );

    // --- conservation ----------------------------------------------------------
    assert_asset_conservation(
        inputs.asset_amount,
        choices.output_slot_classes,
        output_amounts,
        choices.asset_burn_amount,
    );
    assert_native_fee_conservation(
        inputs.native_amount,
        choices.open_fee_amount,
        native_change.amount,
        native_relay_output.amount,
    );

    // --- the two authorizations -------------------------------------------------
    let (private_value, commitment): (PrivateValue<N_IN, N_OUT, SHAPE>, Field) =
        build_private_value(choices, inputs.input_commitments, inputs.nullifiers, bodies);
    // The two roles approve the same private value under different domains,
    // so neither approval reads as the other, nor as a one-account transfer.
    // The sponsor's action names the authenticated contract it pays for.
    let action = sponsored_transfer_action_commitment(pcash_chain_id, commitment);
    verify_first_app(primary_vk);
    verify_next_app(fee_vk);
    let entry = verify_event(
        event_statement,
        event_application_vk,
        action,
        recent_pcash_block_hash,
    );
    assert_rule_statement(
        primary_statement,
        primary_account.authorization,
        action,
        recent_pcash_block_hash,
        entry,
    );
    assert_rule_statement(
        fee_statement,
        fee_account.authorization,
        contract_fee_sponsorship_action_commitment(pcash_chain_id, commitment, primary.address),
        recent_pcash_block_hash,
        entry,
    );

    transaction_statement(
        pcash_chain_id,
        recent_pcash_block_hash,
        private_value,
        events_commitment(entry, event_salt),
    )
}

// The transfer kernel: one account's private-value action. The selected rule is
// the first application circuit and the transaction's event application is the
// second; the rule's private statement is linked through the databus.
// Historical account membership is required unless every input is DUMMY.
// All-dummy actions open a supplied rule set, not installed account authority.
// Asset creation and sponsored transfer use their own protocol
// kernels and converge on the same private-value hiding kernel.

use crate::authorization::authentication::{AuthorizedAccount, open_account};
use crate::authorization::statement::{
    assert_rule_statement, RULE_STATEMENT_LENGTH, transfer_action_commitment,
};
use crate::events::{EVENT_STATEMENT_LENGTH, events_commitment, verify_event};
use crate::ledger::opening::{open_transfer_inputs, open_value_state};
use crate::ledger::private_value::{
    PrivateValue, PrivateValueChoices, SLOT_CLASS_DUMMY, transaction_statement,
};
use crate::ledger::section::{
    assert_asset_conservation, assert_native_conservation, build_private_value, output_bodies,
};
use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, STATE_TREE_DEPTH};
use crate::primitives::types::InputNoteWitness;
use crate::recursion::{AppVerificationKey, verify_first_app};

pub fn transfer<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    choices: PrivateValueChoices<N_IN, N_OUT>,
    output_owner_commitments: [Field; N_OUT],
    output_dummy_secrets: [Field; N_OUT],
    output_amounts: [Field; N_OUT],
    asset_id: Field,
    dummy_input_seed: Field,
    // Rule-defined replay identity per APPLICATION slot; ignored otherwise.
    replay_ids: [Field; N_IN],
    block_header_state_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    output_root: Field,
    state_output_siblings: [Field; STATE_TREE_DEPTH],
    account_state_root: Field,
    state_account_siblings: [Field; STATE_TREE_DEPTH],
    account: AuthorizedAccount,
    // The transfer kernel acts for a user or a contract account.
    account_kind: Field,
    owner_inputs: [InputNoteWitness; N_IN],
    rule_statement: [Field; RULE_STATEMENT_LENGTH],
    authorization_vk: AppVerificationKey,
    event_statement: [Field; EVENT_STATEMENT_LENGTH],
    event_application_vk: AppVerificationKey,
    event_salt: Field,
) -> [Field; N_IN + N_OUT + 9] {
    open_value_state(
        recent_pcash_block_hash,
        block_header_state_siblings,
        output_root,
        state_output_siblings,
        account_state_root,
        state_account_siblings,
    );

    let (account_root, opening) = open_account(account, account_kind, authorization_vk.hash);
    let mut all_inputs_dummy = true;
    for i in 0..N_IN {
        all_inputs_dummy &= choices.input_slot_classes[i] == SLOT_CLASS_DUMMY;
    }
    assert(
        all_inputs_dummy | (account_root == account_state_root),
        "account must be in the account state tree",
    );

    // APPLICATION slots require installed account membership above, even when
    // no note is spent. Positive real outputs still require conserved inputs.
    let inputs = open_transfer_inputs(
        choices.input_slot_classes,
        opening,
        opening,
        output_root,
        asset_id,
        dummy_input_seed,
        owner_inputs,
        replay_ids,
    );
    let bodies = output_bodies(
        choices.output_slot_classes,
        asset_id,
        output_owner_commitments,
        output_dummy_secrets,
        output_amounts,
    );
    assert_native_conservation(
        inputs.native_amount,
        choices.output_slot_classes,
        output_amounts,
        choices.open_fee_amount,
    );
    assert_asset_conservation(
        inputs.asset_amount,
        choices.output_slot_classes,
        output_amounts,
        choices.asset_burn_amount,
    );

    let (private_value, commitment): (PrivateValue<N_IN, N_OUT, SHAPE>, Field) =
        build_private_value(choices, inputs.input_commitments, inputs.nullifiers, bodies);
    let action = transfer_action_commitment(pcash_chain_id, commitment);
    verify_first_app(authorization_vk);
    let entry = verify_event(
        event_statement,
        event_application_vk,
        action,
        recent_pcash_block_hash,
    );
    assert_rule_statement(
        rule_statement,
        opening.authorization,
        action,
        recent_pcash_block_hash,
        entry,
    );

    transaction_statement(
        pcash_chain_id,
        recent_pcash_block_hash,
        private_value,
        events_commitment(entry, event_salt),
    )
}

// The ledger rules shared by every proof-carrying transaction type: notes, the
// private value and its commitment, the private-value section, input openings,
// assets, and the native fee relation.
pub mod note;
pub mod opening;
pub mod asset;
pub mod private_value;
pub mod section;
pub mod fee_payment;

// Fixed commitments for the protocol-owned standard fungible-asset relations.
// Nonzero assets have one transfer/burn law and one fixed, one-shot creation.

use crate::generated::pcash_constants::{
    ASSET_CREATION_MARKER_DOMAIN, ASSET_ID_DOMAIN, ASSET_SECRET_COMMITMENT_DOMAIN,
};
use crate::primitives::hash::pcash_hash;
use crate::primitives::params::MAX_ASSET_SUPPLY;
use crate::primitives::range::assert_asset_aggregate;

pub fn asset_secret_commitment(asset_secret: Field) -> Field {
    pcash_hash([ASSET_SECRET_COMMITMENT_DOMAIN, asset_secret])
}

pub fn standard_fungible_asset_id(
    metadata_commitment: Field,
    initial_supply: Field,
    asset_secret_commitment: Field,
) -> Field {
    assert_asset_aggregate(initial_supply);
    // The asset law is independent of the selected transaction capacity.
    assert_asset_aggregate(MAX_ASSET_SUPPLY - initial_supply);
    pcash_hash(
        [ASSET_ID_DOMAIN, metadata_commitment, initial_supply, asset_secret_commitment],
    )
}

// The asset ID fixes the asset secret through its commitment, so the
// marker is one-shot per asset.
pub fn asset_creation_marker(asset_id: Field, asset_secret: Field) -> Field {
    pcash_hash([ASSET_CREATION_MARKER_DOMAIN, asset_id, asset_secret])
}

mod tests {
    use crate::primitives::params::MAX_ASSET_SUPPLY;
    use super::{asset_creation_marker, asset_secret_commitment, standard_fungible_asset_id};

    #[test]
    fn test_asset_id_and_creation_marker_domains_are_disjoint() {
        let secret_commitment = asset_secret_commitment(0x123);
        let id = standard_fungible_asset_id(0x789, 1_000_000, secret_commitment);
        assert(id != asset_creation_marker(id, 0x789));
    }

    #[test]
    fn test_asset_id_binds_every_field() {
        let secret_commitment = asset_secret_commitment(0x123);
        let base = standard_fungible_asset_id(0x789, 1_000_000, secret_commitment);
        assert(base != standard_fungible_asset_id(0x790, 1_000_000, secret_commitment));
        assert(base != standard_fungible_asset_id(0x789, 1_000_001, secret_commitment));
        assert(base != standard_fungible_asset_id(0x789, 1_000_000, secret_commitment + 1));
    }

    // Zero is an ordinary definition value: no metadata, no supply, or a
    // secret anyone can guess. A zero supply admits no positive asset output.
    #[test]
    fn test_asset_id_accepts_zero_definition_fields() {
        let id = standard_fungible_asset_id(0, 0, asset_secret_commitment(0));
        assert(id != 0);
        assert(id != standard_fungible_asset_id(0, 1, asset_secret_commitment(0)));
    }

    #[test]
    fn test_initial_supply_accepts_asset_law_maximum() {
        let _ = standard_fungible_asset_id(2, MAX_ASSET_SUPPLY, 3);
    }

    #[test(should_fail)]
    fn test_initial_supply_rejects_more_than_the_asset_law_maximum() {
        let _ = standard_fungible_asset_id(2, MAX_ASSET_SUPPLY + 1, 3);
    }
}

// A native-only account action: one account's native notes fund the open
// fee, an optional private relay output, and at most one change note.
//
// This is the value relation of every fee-bearing account action. A user
// account update funds its own fee this way, and a sponsored contract-account
// creation is funded this way by the sponsor. Both build the same private value
// as a type-0 transaction, and the node checks their fee section as it checks
// one. The section does not post issuanceOwnerCommitment: the node supplies
// zero there, and the action earns no issuance.
//
// The change secret is a free witness: change returns to a real party who
// keeps the secret, and the authorizing rule binds whichever opening it
// approved. Zero fee with every slot dummy is a valid degenerate payment.

use crate::authorization::authentication::AccountOpening;
use crate::ledger::note::{dummy_nullifier, owner_commitment};
use crate::ledger::opening::{open_native_notes, OpenedInputs};
use crate::ledger::private_value::{
    PrivateValue, PrivateValueChoices, SLOT_CLASS_DUMMY, SLOT_CLASS_NATIVE,
};
use crate::ledger::section::{build_private_value, output_bodies};
use crate::primitives::types::InputNoteWitness;

pub struct NativeChange {
    pub slot: u32,
    pub secret: Field,
    pub amount: Field,
}

pub struct NativeRelayOutput {
    pub slot: u32,
    pub amount: Field,
}

/// The output owners and amounts of the payer's change note and the optional
/// private relay note. A nonzero change or relay amount lands in its own
/// NATIVE slot, and change opens to the payer's address under the declared
/// secret; every other output keeps its witnessed owner and a zero amount.
///
/// The caller passes the result to output_bodies, which provides the nonzero
/// and range checks: it rejects a real output whose amount is zero or wider
/// than 128 bits. Every NATIVE output is therefore the change or the relay
/// note, and both amounts are bounded. With a zero asset ID, output_bodies also
/// rejects an ASSET output.
pub fn native_change_outputs<let N_OUT: u32>(
    output_slot_classes: [Field; N_OUT],
    output_owner_commitments: [Field; N_OUT],
    payer_address: Field,
    change: NativeChange,
    relay: NativeRelayOutput,
) -> ([Field; N_OUT], [Field; N_OUT]) {
    if relay.amount != 0 {
        assert(relay.slot < N_OUT, "relay slot must be an output slot");
        if change.amount != 0 {
            assert(relay.slot != change.slot, "relay and change slots must differ");
        }
        assert(
            output_slot_classes[relay.slot] == SLOT_CLASS_NATIVE,
            "relay slot must hold a native output",
        );
    }
    if change.amount != 0 {
        assert(change.slot < N_OUT, "change slot must be an output slot");
        assert(
            output_slot_classes[change.slot] == SLOT_CLASS_NATIVE,
            "change slot must hold a native output",
        );
    }
    let change_owner = owner_commitment(payer_address, change.secret);
    let mut owners = output_owner_commitments;
    let mut amounts = [0; N_OUT];
    for i in 0..N_OUT {
        let is_native = output_slot_classes[i] == SLOT_CLASS_NATIVE;
        if is_native & (i == change.slot) {
            amounts[i] = change.amount;
            if change.amount != 0 {
                owners[i] = change_owner;
            }
        }
        if (relay.amount != 0) & is_native & (i == relay.slot) {
            amounts[i] = relay.amount;
        }
    }
    (owners, amounts)
}

/// A fee payment's inputs: NATIVE notes of the payer, and DUMMY padding.
fn open_fee_payment_inputs<let N_IN: u32>(
    input_slot_classes: [Field; N_IN],
    payer: AccountOpening,
    output_root: Field,
    dummy_input_seed: Field,
    native_inputs: [InputNoteWitness; N_IN],
) -> OpenedInputs<N_IN> {
    let mut inputs = open_native_notes(input_slot_classes, payer, output_root, native_inputs);
    for i in 0..N_IN {
        let class = input_slot_classes[i];
        if class == SLOT_CLASS_DUMMY {
            inputs.nullifiers[i] = dummy_nullifier(dummy_input_seed, i as Field);
        } else {
            assert(class == SLOT_CLASS_NATIVE, "fee payment input must be native or dummy");
        }
    }
    inputs
}

pub fn assert_native_fee_conservation(
    native_sum_in: Field,
    open_fee_amount: Field,
    change_amount: Field,
    relay_amount: Field,
) {
    assert(
        native_sum_in == open_fee_amount + change_amount + relay_amount,
        "native inputs must equal native outputs plus the open fee",
    );
}

/// The complete native fee-payment relation for one payer. Returns the private
/// value and its commitment.
pub fn native_fee_payment<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    choices: PrivateValueChoices<N_IN, N_OUT>,
    payer: AccountOpening,
    output_root: Field,
    native_inputs: [InputNoteWitness; N_IN],
    dummy_input_seed: Field,
    output_owner_commitments: [Field; N_OUT],
    output_dummy_secrets: [Field; N_OUT],
    change: NativeChange,
    relay: NativeRelayOutput,
) -> (PrivateValue<N_IN, N_OUT, SHAPE>, Field) {
    let inputs = open_fee_payment_inputs(
        choices.input_slot_classes,
        payer,
        output_root,
        dummy_input_seed,
        native_inputs,
    );
    let (owners, amounts) = native_change_outputs(
        choices.output_slot_classes,
        output_owner_commitments,
        payer.address,
        change,
        relay,
    );
    let bodies = output_bodies(
        choices.output_slot_classes,
        0,
        owners,
        output_dummy_secrets,
        amounts,
    );
    assert(choices.asset_burn_amount == 0, "asset burn amount must be zero");
    assert_native_fee_conservation(
        inputs.native_amount,
        choices.open_fee_amount,
        change.amount,
        relay.amount,
    );
    build_private_value(choices, inputs.input_commitments, inputs.nullifiers, bodies)
}

mod tests {
    use crate::authorization::authentication::AccountOpening;
    use crate::ledger::note::{
        dummy_nullifier, full_output_commitment, note_body_commitment, nullifier, owner_commitment,
    };
    use crate::ledger::note::tests::single_note_opening;
    use crate::ledger::private_value::{
        PrivateValue, PrivateValueChoices, SLOT_CLASS_APPLICATION, SLOT_CLASS_ASSET,
        SLOT_CLASS_DUMMY, SLOT_CLASS_NATIVE,
    };
    use crate::primitives::params::MERKLE_DEPTH;
    use crate::primitives::types::{InputNoteWitness, Note};
    use super::{
        assert_native_fee_conservation, native_change_outputs, native_fee_payment, NativeChange,
        NativeRelayOutput,
    };

    global OWNER: Field = 0x1111111111111111111111111111111111111111;

    fn classes(change_slot_native: bool) -> [Field; 5] {
        [
            if change_slot_native {
                SLOT_CLASS_NATIVE
            } else {
                SLOT_CLASS_DUMMY
            },
            SLOT_CLASS_DUMMY,
            SLOT_CLASS_DUMMY,
            SLOT_CLASS_DUMMY,
            SLOT_CLASS_DUMMY,
        ]
    }

    fn absent_relay() -> NativeRelayOutput {
        NativeRelayOutput { slot: 1, amount: 0 }
    }

    // A fee payment from DUMMY inputs only, with no open fee: the outputs are
    // all that is checked before conservation.
    fn pay_without_inputs(
        output_slot_classes: [Field; 5],
        change: NativeChange,
        relay: NativeRelayOutput,
    ) {
        let choices = PrivateValueChoices {
            open_fee_amount: 0,
            issuance_owner_commitment: 0,
            not_before_timestamp: 0,
            valid_until_timestamp: 2000000000,
            carrier_context_hash: 0,
            asset_burn_amount: 0,
            delivery_commitment: 0x61,
            input_slot_classes: [SLOT_CLASS_DUMMY; 4],
            output_slot_classes,
        };
        let no_inputs = [
            InputNoteWitness {
                output_index: 0,
                note_secret: 0,
                amount: 0,
                siblings: [0; MERKLE_DEPTH],
            }; 4
        ];
        let _: (PrivateValue<4, 5, 0>, Field) = native_fee_payment(
            choices,
            AccountOpening { address: OWNER, nk: 0x0b2, entry: 0x0b4, authorization: 0x0b5 },
            0,
            no_inputs,
            0xaaa,
            [0x111; 5],
            [1, 2, 3, 4, 5],
            change,
            relay,
        );
    }

    #[test]
    fn test_change_returns_to_the_payer_in_the_declared_slot() {
        let change = NativeChange { slot: 0, secret: 0x777, amount: 1500 };
        let (owners, amounts) = native_change_outputs(
            classes(true),
            [0x90, 0x91, 0x92, 0x93, 0x94],
            OWNER,
            change,
            absent_relay(),
        );
        assert(owners == [owner_commitment(OWNER, 0x777), 0x91, 0x92, 0x93, 0x94]);
        assert(amounts == [1500, 0, 0, 0, 0]);
    }

    #[test]
    fn test_relay_output_keeps_its_owner_without_change() {
        let change = NativeChange { slot: 0, secret: 0, amount: 0 };
        let relay = NativeRelayOutput { slot: 0, amount: 500 };
        let (owners, amounts) =
            native_change_outputs(classes(true), [0xabc, 0, 0, 0, 0], OWNER, change, relay);
        assert(owners == [0xabc, 0, 0, 0, 0]);
        assert(amounts == [500, 0, 0, 0, 0]);
    }

    #[test]
    fn test_accepts_zero_change_with_no_native_output() {
        let (owners, amounts) = native_change_outputs(
            classes(false),
            [0x90, 0x91, 0x92, 0x93, 0x94],
            OWNER,
            NativeChange { slot: 0, secret: 0, amount: 0 },
            absent_relay(),
        );
        assert(owners == [0x90, 0x91, 0x92, 0x93, 0x94]);
        assert(amounts == [0, 0, 0, 0, 0]);
    }

    #[test(should_fail_with = "change slot must hold a native output")]
    fn test_rejects_change_in_a_slot_that_is_not_native() {
        let _ = native_change_outputs(
            classes(false),
            [0; 5],
            OWNER,
            NativeChange { slot: 0, secret: 0x777, amount: 1500 },
            absent_relay(),
        );
    }

    // Conservation counts the relay amount, so it must land in a NATIVE output.
    #[test(should_fail_with = "relay slot must hold a native output")]
    fn test_rejects_relay_in_a_slot_that_is_not_native() {
        let _ = native_change_outputs(
            classes(true),
            [0; 5],
            OWNER,
            NativeChange { slot: 0, secret: 0, amount: 0 },
            NativeRelayOutput { slot: 1, amount: 500 },
        );
    }

    #[test]
    fn test_private_relay_fee_is_funded_by_native_inputs() {
        assert_native_fee_conservation(100, 0, 60, 40);
    }

    #[test(should_fail_with = "native inputs must equal native outputs plus the open fee")]
    fn test_rejects_underfunded_private_relay_fee() {
        assert_native_fee_conservation(100, 0, 60, 41);
    }

    // A zero change secret is the payer's choice: the change still opens to
    // the payer, under a guessable owner commitment.
    #[test]
    fn test_accepts_change_under_a_zero_secret() {
        let change = NativeChange { slot: 0, secret: 0, amount: 1500 };
        let (owners, _) =
            native_change_outputs(classes(true), [0; 5], OWNER, change, absent_relay());
        assert(owners[0] == owner_commitment(OWNER, 0));
    }

    // A NATIVE output that is neither the change nor the relay note gets a zero
    // amount, which output_bodies rejects.
    #[test(should_fail_with = "real output amount must be nonzero")]
    fn test_rejects_a_native_output_without_change() {
        pay_without_inputs(
            classes(true),
            NativeChange { slot: 0, secret: 0, amount: 0 },
            absent_relay(),
        );
    }

    #[test(should_fail_with = "real output amount must be nonzero")]
    fn test_rejects_a_native_output_in_another_slot() {
        let mut output_slot_classes = classes(true);
        output_slot_classes[1] = SLOT_CLASS_NATIVE;
        pay_without_inputs(
            output_slot_classes,
            NativeChange { slot: 1, secret: 0x777, amount: 1500 },
            absent_relay(),
        );
    }

    // A fee payment has no asset ID, so output_bodies rejects an ASSET output.
    #[test(should_fail_with = "asset ID must be nonzero for an asset slot")]
    fn test_rejects_an_asset_output() {
        let mut output_slot_classes = classes(false);
        output_slot_classes[0] = SLOT_CLASS_ASSET;
        pay_without_inputs(
            output_slot_classes,
            NativeChange { slot: 1, secret: 0, amount: 0 },
            absent_relay(),
        );
    }

    fn fee_payment_fixture() -> (PrivateValueChoices<4, 5>, AccountOpening, Note) {
        let payer =
            AccountOpening { address: OWNER, nk: 0x0b2, entry: 0x0b4, authorization: 0x0b5 };
        let choices = PrivateValueChoices {
            open_fee_amount: 200,
            issuance_owner_commitment: 0,
            not_before_timestamp: 0,
            valid_until_timestamp: 2000000000,
            carrier_context_hash: 0,
            asset_burn_amount: 0,
            delivery_commitment: 0x61,
            input_slot_classes: [
                SLOT_CLASS_NATIVE,
                SLOT_CLASS_DUMMY,
                SLOT_CLASS_DUMMY,
                SLOT_CLASS_DUMMY,
            ],
            output_slot_classes: classes(true),
        };
        (
            choices, payer,
            Note { owner: payer.address, note_secret: 0x5ec, asset_id: 0, amount: 1000 },
        )
    }

    // A fee payment spending the fixture's one native note of 1000.
    fn pay_from_note(
        choices: PrivateValueChoices<4, 5>,
        change: NativeChange,
        relay: NativeRelayOutput,
    ) -> PrivateValue<4, 5, 0> {
        let (_, payer, note) = fee_payment_fixture();
        let (witness, root) = single_note_opening(note);
        let mut inputs = [
            InputNoteWitness {
                output_index: 0,
                note_secret: 0,
                amount: 0,
                siblings: [0; MERKLE_DEPTH],
            }; 4
        ];
        inputs[0] = witness;
        let (value, _) = native_fee_payment(
            choices,
            payer,
            root,
            inputs,
            0xaaa,
            [0; 5],
            [0, 2, 3, 4, 5],
            change,
            relay,
        );
        value
    }

    #[test]
    fn test_fee_payment_derives_its_private_value() {
        let (choices, payer, note) = fee_payment_fixture();
        let value = pay_from_note(
            choices,
            NativeChange { slot: 0, secret: 0x777, amount: 800 },
            absent_relay(),
        );
        let leaf = full_output_commitment(note, 0);
        assert(value.input_commitments == [leaf, 0, 0, 0]);
        assert(value.nullifiers[0] == nullifier(leaf, payer.nk, 0x5ec));
        assert(value.nullifiers[3] == dummy_nullifier(0xaaa, 3));
        assert(
            value.output_body_commitments[0]
                == note_body_commitment(owner_commitment(payer.address, 0x777), 0, 800),
        );
    }

    // The note pays the open fee, change in slot 0 and a relay note in slot 1:
    // 1000 = 200 + 700 + 100.
    fn change_and_relay() -> (PrivateValueChoices<4, 5>, NativeChange, NativeRelayOutput) {
        let (mut choices, _, _) = fee_payment_fixture();
        choices.output_slot_classes[1] = SLOT_CLASS_NATIVE;
        (
            choices, NativeChange { slot: 0, secret: 0x777, amount: 700 },
            NativeRelayOutput { slot: 1, amount: 100 },
        )
    }

    #[test]
    fn test_fee_payment_pays_change_and_a_relay_note() {
        let (choices, change, relay) = change_and_relay();
        let value = pay_from_note(choices, change, relay);
        assert(value.output_body_commitments[1] == note_body_commitment(0, 0, 100));
    }

    // A balanced payment with a third NATIVE output: that output gets a zero
    // amount, which output_bodies rejects.
    #[test(should_fail_with = "real output amount must be nonzero")]
    fn test_fee_payment_rejects_a_native_output_beside_change_and_relay() {
        let (mut choices, change, relay) = change_and_relay();
        choices.output_slot_classes[2] = SLOT_CLASS_NATIVE;
        let _ = pay_from_note(choices, change, relay);
    }

    #[test(should_fail_with = "relay and change slots must differ")]
    fn test_fee_payment_rejects_change_and_relay_in_one_slot() {
        let (mut choices, change, mut relay) = change_and_relay();
        choices.output_slot_classes[1] = SLOT_CLASS_DUMMY;
        relay.slot = change.slot;
        let _ = pay_from_note(choices, change, relay);
    }

    // Conservation holds in the field, 1000 = 1001 + (p - 1), but the change
    // amount is not a 128-bit amount. output_bodies range-checks the amount in
    // the change slot.
    #[test(should_fail)]
    fn test_fee_payment_rejects_a_wrapped_change_amount() {
        let (mut choices, _, _) = fee_payment_fixture();
        choices.open_fee_amount = 1001;
        let _ = pay_from_note(
            choices,
            NativeChange { slot: 0, secret: 0x777, amount: -1 },
            absent_relay(),
        );
    }

    // The same with the relay amount, range-checked in the relay slot.
    #[test(should_fail)]
    fn test_fee_payment_rejects_a_wrapped_relay_amount() {
        let (mut choices, _, _) = fee_payment_fixture();
        choices.open_fee_amount = 1001;
        let _ = pay_from_note(
            choices,
            NativeChange { slot: 1, secret: 0, amount: 0 },
            NativeRelayOutput { slot: 0, amount: -1 },
        );
    }

    #[test(should_fail_with = "fee payment input must be native or dummy")]
    fn test_fee_payment_rejects_a_marker() {
        let (mut choices, payer, _) = fee_payment_fixture();
        choices.input_slot_classes[0] = SLOT_CLASS_APPLICATION;
        choices.output_slot_classes = classes(false);
        choices.open_fee_amount = 0;
        let inputs = [
            InputNoteWitness {
                output_index: 0,
                note_secret: 0,
                amount: 0,
                siblings: [0; MERKLE_DEPTH],
            }; 4
        ];
        let _: (PrivateValue<4, 5, 0>, Field) = native_fee_payment(
            choices,
            payer,
            0,
            inputs,
            0xaaa,
            [0; 5],
            [1, 2, 3, 4, 5],
            NativeChange { slot: 0, secret: 0, amount: 0 },
            absent_relay(),
        );
    }
}

// PCASH keys, note commitments, and nullifiers.
//
// Every formula below is a length-tagged Poseidon2 sponge (`pcash_hash`) over
// the domain tag followed by the field operands, in the exact order given by
// the spec. Order is normative. A note's owner is the uint160 address of the
// account that may spend it; padding notes belong to address zero, where no
// account exists.

use crate::generated::pcash_constants::{
    APPLICATION_NULLIFIER_DOMAIN, DUMMY_NULLIFIER_DOMAIN, NOTE_BODY_COMMITMENT_DOMAIN,
    NOTE_NULLIFIER_KEY_DOMAIN, NULLIFIER_DOMAIN, NULLIFIER_KEY_COMMITMENT_DOMAIN,
    OUTPUT_COMMITMENT_DOMAIN, OWNER_COMMITMENT_DOMAIN,
};
use crate::primitives::hash::pcash_hash;
use crate::primitives::range::assert_amount;
use crate::primitives::types::{InputNoteWitness, Note};
use crate::state::merkle::binary_root_from_index;

// ===========================================================================
// Account nullifier-key hierarchy
// ===========================================================================

// nullifierKeyCommitment = poseidon(NULLIFIER_KEY_COMMITMENT_DOMAIN, nkRoot).
// Published in every account; unrelated to the global spent-nullifier tree root.
pub fn nullifier_key_commitment(nk_root: Field) -> Field {
    pcash_hash([NULLIFIER_KEY_COMMITMENT_DOMAIN, nk_root])
}

// noteNk = poseidon(NOTE_NULLIFIER_KEY_DOMAIN, nkRoot). nk for note nullifiers.
pub fn note_nk(nk_root: Field) -> Field {
    pcash_hash([NOTE_NULLIFIER_KEY_DOMAIN, nk_root])
}

// ===========================================================================
// Note bodies and indexed output commitments
// ===========================================================================

// ownerCommitment = poseidon(OWNER_COMMITMENT_DOMAIN, uint160(owner), noteSecret).
pub fn owner_commitment(owner: Field, note_secret: Field) -> Field {
    pcash_hash([OWNER_COMMITMENT_DOMAIN, owner, note_secret])
}

// noteBodyCommitment = poseidon(
//     NOTE_BODY_COMMITMENT_DOMAIN, ownerCommitment, assetId, amount,
// ).
pub fn note_body_commitment(
    owner_commitment_value: Field,
    asset_id: Field,
    amount: Field,
) -> Field {
    pcash_hash(
        [NOTE_BODY_COMMITMENT_DOMAIN, owner_commitment_value, asset_id, amount],
    )
}

// outputCommitment = poseidon(OUTPUT_COMMITMENT_DOMAIN, outputBody, outputIndex).
// Each ordinary note body has its own indexed output commitment.
pub fn output_commitment(output_body: Field, output_index: Field) -> Field {
    pcash_hash([OUTPUT_COMMITMENT_DOMAIN, output_body, output_index])
}

// Convenience: full three-layer commitment for a note at a known output index.
pub fn full_output_commitment(note: Note, output_index: Field) -> Field {
    let oc = owner_commitment(note.owner, note.note_secret);
    let body = note_body_commitment(oc, note.asset_id, note.amount);
    output_commitment(body, output_index)
}

// ===========================================================================
// Nullifiers
// ===========================================================================

// nullifier = poseidon(NULLIFIER_DOMAIN, outputCommitment, noteNk, noteSecret).
pub fn nullifier(
    output_commitment_value: Field,
    note_nk_value: Field,
    note_secret_value: Field,
) -> Field {
    pcash_hash(
        [NULLIFIER_DOMAIN, output_commitment_value, note_nk_value, note_secret_value],
    )
}

// dummyNullifier = poseidon(DUMMY_NULLIFIER_DOMAIN, dummyInputSeed, inputIndex).
// One per DUMMY input slot. The operands name no account, so a seed shared
// with anyone else yields the same nullifiers; the wallet draws a fresh
// unpredictable seed for every action.
pub fn dummy_nullifier(dummy_input_seed: Field, input_index: Field) -> Field {
    pcash_hash([DUMMY_NULLIFIER_DOMAIN, dummy_input_seed, input_index])
}

// applicationNullifier = poseidon(
//     APPLICATION_NULLIFIER_DOMAIN, uint160(address),
//     selectedEntryCommitment, replayId).
//
// The account and the exact selected account-rule entry supply scope; `replayId`
// is defined entirely by that rule and is never interpreted here.
//
// The operand list is deliberately closed. It binds no slot index, no input note
// commitment, no output, no fee, no timestamp, no recent root, and no proof
// randomness — if it bound any of them a party could reshape the transaction and
// derive a fresh marker for the same fact, which is exactly the replay this
// prevents. It also omits pcashChainId: no PCASH nullifier binds the chain, and
// the surrounding contract identity is chain-independent by construction.
pub fn application_nullifier(
    address: Field,
    selected_entry_commitment: Field,
    replay_id: Field,
) -> Field {
    pcash_hash(
        [APPLICATION_NULLIFIER_DOMAIN, address, selected_entry_commitment, replay_id],
    )
}

// ===========================================================================
// Input openings
// ===========================================================================

// One real input note, opened against the account that owns it.
//
// The note is built from the owner the kernel authenticated, the slot's
// namespace, and the witnessed secret and amount, so it belongs to that owner and
// namespace by construction. Every relation that spends notes derives the same
// three values here: the input commitment, its membership under the
// authenticated output root, and the canonical nullifier. Native and asset note
// amounts share the same integer bound. Keeping it here makes every caller's
// conservation sum bounded; capacity is at most 64 notes, far below the field
// modulus even at the largest per-note amount.
pub struct OpenedInput {
    pub input_commitment: Field,
    pub nullifier: Field,
    pub amount: Field,
}

pub fn open_owner_input(
    witness: InputNoteWitness,
    owner: Field,
    nk: Field,
    asset_id: Field,
    output_root: Field,
) -> OpenedInput {
    assert_amount(witness.amount);
    assert(witness.amount != 0, "input amount must be nonzero");
    let note = Note { owner, note_secret: witness.note_secret, asset_id, amount: witness.amount };
    let input_commitment = full_output_commitment(note, witness.output_index);
    assert(
        binary_root_from_index(input_commitment, witness.output_index, witness.siblings)
            == output_root,
        "input note must be in the output tree",
    );
    OpenedInput {
        input_commitment,
        nullifier: nullifier(input_commitment, nk, witness.note_secret),
        amount: witness.amount,
    }
}

pub(crate) mod tests {
    use crate::generated::pcash_constants::{
        APPLICATION_NULLIFIER_DOMAIN, DUMMY_NULLIFIER_DOMAIN, NOTE_BODY_COMMITMENT_DOMAIN,
        NOTE_NULLIFIER_KEY_DOMAIN, NULLIFIER_DOMAIN, NULLIFIER_KEY_COMMITMENT_DOMAIN,
        OUTPUT_COMMITMENT_DOMAIN, OWNER_COMMITMENT_DOMAIN,
    };
    use crate::primitives::hash::pcash_hash;
    use crate::primitives::params::MERKLE_DEPTH;
    use crate::primitives::types::{InputNoteWitness, Note};
    use crate::state::merkle::binary_root_from_index;
    use super::{
        application_nullifier, dummy_nullifier, full_output_commitment, note_body_commitment,
        note_nk, nullifier, nullifier_key_commitment, open_owner_input, output_commitment,
        owner_commitment,
    };

    // A one-leaf output tree holding `note` at index 0, and the witness that opens it.
    pub(crate) fn single_note_opening(note: Note) -> (InputNoteWitness, Field) {
        let siblings = [0; MERKLE_DEPTH];
        let root = binary_root_from_index(full_output_commitment(note, 0), 0, siblings);
        (
            InputNoteWitness {
                output_index: 0,
                note_secret: note.note_secret,
                amount: note.amount,
                siblings,
            }, root,
        )
    }

    // Cross-check the module wiring against `pcash_hash` computed directly from
    // the domain tag and operands (the Poseidon agreement test in hash.nr pins
    // pcash_hash to the Rust/TS golden vectors, so these pin the formula layout).

    #[test]
    fn test_key_hierarchy_matches_formula() {
        let nk_root = 0x9999;
        assert(
            nullifier_key_commitment(nk_root)
                == pcash_hash([NULLIFIER_KEY_COMMITMENT_DOMAIN, nk_root]),
        );
        assert(note_nk(nk_root) == pcash_hash([NOTE_NULLIFIER_KEY_DOMAIN, nk_root]));
    }

    #[test]
    fn test_note_commitment_layers_match_formula() {
        let owner = 0xabc;
        let ns = 0xbeef;
        let amount = 1000;
        let oc = owner_commitment(owner, ns);
        assert(oc == pcash_hash([OWNER_COMMITMENT_DOMAIN, owner, ns]));
        let body = note_body_commitment(oc, 0, amount);
        assert(body == pcash_hash([NOTE_BODY_COMMITMENT_DOMAIN, oc, 0, amount]));
        let nc = output_commitment(body, 7);
        assert(nc == pcash_hash([OUTPUT_COMMITMENT_DOMAIN, body, 7]));

        let note = Note { owner, note_secret: ns, asset_id: 0, amount };
        assert(full_output_commitment(note, 7) == nc);
        // output index is a structural uniqueness source.
        assert(full_output_commitment(note, 8) != nc);
    }

    #[test]
    fn test_nullifier_vs_dummy_differ() {
        let nk = note_nk(0x9999);
        let secret = 0xbeef;
        let real = nullifier(0x1234, nk, secret);
        assert(real == pcash_hash([NULLIFIER_DOMAIN, 0x1234, nk, secret]));
        let dummy = dummy_nullifier(0xaaaa, 0);
        assert(dummy == pcash_hash([DUMMY_NULLIFIER_DOMAIN, 0xaaaa, 0]));
        assert(real != dummy);
    }

    // A zero seed is an ordinary operand: its markers are well defined and
    // nonzero, and like any seed known to others, they collide with theirs.
    #[test]
    fn test_dummy_nullifier_accepts_a_zero_seed() {
        let dummy = dummy_nullifier(0, 0);
        assert(dummy == pcash_hash([DUMMY_NULLIFIER_DOMAIN, 0, 0]));
        assert(dummy != 0);
        assert(dummy != dummy_nullifier(0, 1));
    }

    #[test]
    fn test_application_nullifier_binds_address_entry_and_replay() {
        let base = application_nullifier(0x111, 0x222, 0x333);
        assert(base == pcash_hash([APPLICATION_NULLIFIER_DOMAIN, 0x111, 0x222, 0x333]));
        // Every operand is load-bearing scope.
        assert(base != application_nullifier(0x112, 0x222, 0x333));
        assert(base != application_nullifier(0x111, 0x223, 0x333));
        assert(base != application_nullifier(0x111, 0x222, 0x334));
        // Disjoint from the other note-free markers and from a real note nullifier.
        assert(base != dummy_nullifier(0x111, 0));
        assert(base != nullifier(0x111, note_nk(0x222), 0x333));
    }

    // Replay ID zero is an ordinary one-shot marker, still scoped to the
    // account and the rule entry.
    #[test]
    fn test_application_nullifier_accepts_replay_id_zero() {
        let marker = application_nullifier(0x111, 0x222, 0);
        assert(marker == pcash_hash([APPLICATION_NULLIFIER_DOMAIN, 0x111, 0x222, 0]));
        assert(marker != 0);
        assert(marker == application_nullifier(0x111, 0x222, 0));
        assert(marker != application_nullifier(0x112, 0x222, 0));
        assert(marker != application_nullifier(0x111, 0x223, 0));
    }

    // A zero note secret is one more operand: the owner commitment, the output
    // commitment, and the nullifier are all ordinary values, and the nullifier
    // is not zero.
    #[test]
    fn test_zero_note_secret_is_an_ordinary_operand() {
        let note = Note { owner: 0x1234, note_secret: 0, asset_id: 0, amount: 1 };
        let leaf = full_output_commitment(note, 0);
        assert(
            leaf == output_commitment(note_body_commitment(owner_commitment(0x1234, 0), 0, 1), 0),
        );
        let spent = nullifier(leaf, note_nk(0x9999), 0);
        assert(spent == pcash_hash([NULLIFIER_DOMAIN, leaf, note_nk(0x9999), 0]));
        assert(spent != 0);
    }

    // Golden vectors: absolute hex values (not recomputed inline), pinning the full
    // commitment pipeline byte-for-byte. Regenerate only on an intentional formula
    // change and update the reference implementation to match.
    #[test]
    fn test_golden_vectors() {
        // output commitment for owner=0xabc, noteSecret=0xbeef, amount=1000,
        // outputIndex=7.
        let oc = owner_commitment(0xabc, 0xbeef);
        let body = note_body_commitment(oc, 0, 1000);
        assert(body == 0x164a08339c97307e73f91488b75b97cdf0a64d56e2bc7358fe24a4fd7aee46d0);
        assert(
            output_commitment(body, 7)
                == 0x1957bef470681eed3110232bed1596f9af88dd24991d58b8e27231c0ba4e53aa,
        );
    }

    fn check_opened_amount(amount: Field) {
        let (witness, root) =
            single_note_opening(Note { owner: 11, note_secret: 12, asset_id: 0, amount });
        assert(open_owner_input(witness, 11, 13, 0, root).amount == amount);
    }

    #[test]
    fn test_opened_note_accepts_maximum_amount() {
        check_opened_amount(0xffffffffffffffffffffffffffffffff);
    }

    #[test(should_fail)]
    fn test_opened_note_rejects_oversized_amount_even_with_valid_membership() {
        check_opened_amount(0x100000000000000000000000000000000);
    }

    #[test(should_fail)]
    fn test_opened_note_rejects_negative_amount_even_with_valid_membership() {
        check_opened_amount(-1);
    }

    #[test]
    fn test_open_owner_input_derives_commitment_and_nullifier() {
        let note = Note { owner: 0xabc, note_secret: 0xbeef, asset_id: 0, amount: 1000 };
        let (witness, root) = single_note_opening(note);
        let nk = note_nk(0x9999);
        let opened = open_owner_input(witness, 0xabc, nk, 0, root);
        let leaf = full_output_commitment(note, 0);
        assert(opened.input_commitment == leaf);
        assert(opened.nullifier == nullifier(leaf, nk, 0xbeef));
        assert(opened.amount == 1000);
    }

    // A positive note under a zero secret opens under its owner and has one
    // canonical nullifier, so the node's spent-nullifier check rejects a
    // second spend. Native and asset namespaces alike.
    #[test]
    fn test_open_owner_input_spends_a_zero_secret_note_once() {
        let nk = note_nk(0x9999);
        for asset_id in [0, 0x5a] {
            let note = Note { owner: 0xabc, note_secret: 0, asset_id, amount: 1000 };
            let (witness, root) = single_note_opening(note);
            let first = open_owner_input(witness, 0xabc, nk, asset_id, root);
            let second = open_owner_input(witness, 0xabc, nk, asset_id, root);
            assert(first.input_commitment == full_output_commitment(note, 0));
            assert(first.nullifier == nullifier(first.input_commitment, nk, 0));
            assert(first.nullifier != 0);
            assert(second.nullifier == first.nullifier);
        }
    }

    // A note of another owner or namespace is not in the tree the kernel opens.
    #[test(should_fail_with = "input note must be in the output tree")]
    fn test_open_owner_input_rejects_foreign_owner() {
        let (witness, root) = single_note_opening(
            Note { owner: 0xabc, note_secret: 0xbeef, asset_id: 0, amount: 1000 },
        );
        let _ = open_owner_input(witness, 0xabd, note_nk(0x9999), 0, root);
    }

    // The zero-secret note of one owner is not another owner's note.
    #[test(should_fail_with = "input note must be in the output tree")]
    fn test_open_owner_input_rejects_another_owners_zero_secret_note() {
        let (witness, root) = single_note_opening(
            Note { owner: 0xabc, note_secret: 0, asset_id: 0, amount: 1000 },
        );
        let _ = open_owner_input(witness, 0xabd, note_nk(0x9999), 0, root);
    }

    #[test(should_fail_with = "input note must be in the output tree")]
    fn test_open_owner_input_rejects_namespace_mismatch() {
        let (witness, root) = single_note_opening(
            Note { owner: 0xabc, note_secret: 0xbeef, asset_id: 0, amount: 1000 },
        );
        let _ = open_owner_input(witness, 0xabc, note_nk(0x9999), 1, root);
    }

    #[test(should_fail_with = "input amount must be nonzero")]
    fn test_open_owner_input_rejects_zero_amount() {
        let (witness, root) = single_note_opening(
            Note { owner: 0xabc, note_secret: 0xbeef, asset_id: 0, amount: 0 },
        );
        let _ = open_owner_input(witness, 0xabc, note_nk(0x9999), 0, root);
    }
}

// Shared authenticated snapshot and input openings. Each kernel keeps its own
// input grammar; these derive the input commitments, nullifiers and bounded note
// amounts its slots carry. Callers authenticate the accounts and conserve the
// returned amounts.

use crate::authorization::authentication::AccountOpening;
use crate::ledger::note::{application_nullifier, dummy_nullifier, open_owner_input};
use crate::ledger::private_value::{
    SLOT_CLASS_APPLICATION, SLOT_CLASS_ASSET, SLOT_CLASS_ASSET_CREATION, SLOT_CLASS_DUMMY,
    SLOT_CLASS_NATIVE,
};
use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, STATE_TREE_DEPTH};
use crate::primitives::types::InputNoteWitness;
use crate::state::block::{
    block_header_fact, BLOCK_HEADER_KEY_STATE_ROOT, state_fact, STATE_KEY_ACCOUNT_STATE_ROOT,
    STATE_KEY_OUTPUT_ROOT, state_root_from_opening,
};

// Opens the output root under the recent block's header. Returns the state
// root the opening implies, which the header commits.
pub fn open_output_root(
    recent_pcash_block_hash: Field,
    block_header_state_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    output_root: Field,
    state_output_siblings: [Field; STATE_TREE_DEPTH],
) -> Field {
    let state_root =
        state_root_from_opening(output_root, STATE_KEY_OUTPUT_ROOT, state_output_siblings);
    block_header_fact(
        recent_pcash_block_hash,
        BLOCK_HEADER_KEY_STATE_ROOT,
        state_root,
        block_header_state_siblings,
    );
    state_root
}

// Opens the output and account-state roots under the recent block's one state
// root.
pub fn open_value_state(
    recent_pcash_block_hash: Field,
    block_header_state_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    output_root: Field,
    state_output_siblings: [Field; STATE_TREE_DEPTH],
    account_state_root: Field,
    state_account_siblings: [Field; STATE_TREE_DEPTH],
) {
    let state_root = open_output_root(
        recent_pcash_block_hash,
        block_header_state_siblings,
        output_root,
        state_output_siblings,
    );
    state_fact(
        state_root,
        STATE_KEY_ACCOUNT_STATE_ROOT,
        account_state_root,
        state_account_siblings,
    );
}

// The derived input slots, zero in every slot not yet derived, and the opened
// note totals. Every opened amount is nonzero and below 2^128, and there are at
// most 32 inputs, so a total is zero exactly when no note of its class opened.
pub struct OpenedInputs<let N_IN: u32> {
    pub input_commitments: [Field; N_IN],
    pub nullifiers: [Field; N_IN],
    pub native_amount: Field,
    pub asset_amount: Field,
}

fn no_inputs<let N_IN: u32>() -> OpenedInputs<N_IN> {
    OpenedInputs {
        input_commitments: [0; N_IN],
        nullifiers: [0; N_IN],
        native_amount: 0,
        asset_amount: 0,
    }
}

// An APPLICATION marker belongs to the primary account and its selected rule
// entry; the rule defines the replay ID.
pub fn application_marker(primary: AccountOpening, replay_id: Field) -> Field {
    application_nullifier(primary.address, primary.entry, replay_id)
}

// Opens every NATIVE input to the payer and leaves every other slot for the
// caller's own slot rules.
pub fn open_native_notes<let N_IN: u32>(
    input_slot_classes: [Field; N_IN],
    payer: AccountOpening,
    output_root: Field,
    native_inputs: [InputNoteWitness; N_IN],
) -> OpenedInputs<N_IN> {
    let mut result = no_inputs();
    for i in 0..N_IN {
        if input_slot_classes[i] == SLOT_CLASS_NATIVE {
            let opened =
                open_owner_input(native_inputs[i], payer.address, payer.nk, 0, output_root);
            result.input_commitments[i] = opened.input_commitment;
            result.nullifiers[i] = opened.nullifier;
            result.native_amount += opened.amount;
        }
    }
    result
}

// A transfer's inputs: DUMMY, NATIVE, ASSET, and APPLICATION. ASSET and
// APPLICATION belong to the primary, NATIVE belongs to the native payer.
// Passing the same account in both roles gives the transfer kernel's relation.
pub fn open_transfer_inputs<let N_IN: u32>(
    input_slot_classes: [Field; N_IN],
    primary: AccountOpening,
    native_payer: AccountOpening,
    output_root: Field,
    asset_id: Field,
    dummy_input_seed: Field,
    owner_inputs: [InputNoteWitness; N_IN],
    replay_ids: [Field; N_IN],
) -> OpenedInputs<N_IN> {
    let mut result = no_inputs();
    for i in 0..N_IN {
        let class = input_slot_classes[i];
        assert(class != SLOT_CLASS_ASSET_CREATION, "transfer input must not be a creation marker");
        if class == SLOT_CLASS_DUMMY {
            result.nullifiers[i] = dummy_nullifier(dummy_input_seed, i as Field);
        } else if class == SLOT_CLASS_APPLICATION {
            result.nullifiers[i] = application_marker(primary, replay_ids[i]);
        } else {
            // NATIVE or ASSET; the commitment rejects any other class.
            let is_asset = class == SLOT_CLASS_ASSET;
            let account = if is_asset { primary } else { native_payer };
            let namespace = if is_asset {
                assert(asset_id != 0, "asset ID must be nonzero for an asset slot");
                asset_id
            } else {
                0
            };
            let opened = open_owner_input(
                owner_inputs[i],
                account.address,
                account.nk,
                namespace,
                output_root,
            );
            result.input_commitments[i] = opened.input_commitment;
            result.nullifiers[i] = opened.nullifier;
            if is_asset {
                result.asset_amount += opened.amount;
            } else {
                result.native_amount += opened.amount;
            }
        }
    }
    result
}

