// Account commitments and installed-rule authentication. Semantic signing
// rules live in reference_rule_common, not in this protocol library.
pub mod account;
pub mod authentication;
pub mod statement;

// PCASH address accounts and account rules.

use crate::generated::pcash_constants::{
    ACCOUNT_RULE_ENTRY_DOMAIN, ACCOUNT_STATE_COMMITMENT_DOMAIN, ACCOUNT_UPDATE_COMMITMENT_DOMAIN,
};
use crate::primitives::hash::pcash_hash;

pub global ACCOUNT_KIND_USER: Field = 0;
pub global ACCOUNT_KIND_CONTRACT: Field = 1;

// accountStateCommitment = poseidon(ACCOUNT_STATE_COMMITMENT_DOMAIN, uint160(address), nullifierKeyCommitment,
//                       accountRuleSetCommitment, accountKind, accountRevision, receiveKeyHash).
// accountKind: 0 = user, 1 = contract.
// receiveKeyHash = poseidonBytes(RECEIVE_KEY_HASH_DOMAIN, mlKem768PublicKey); zero means no receive key.
// The fields enter as given: every caller either opens the row in the account
// tree or has consensus compare the commitment with one it derives from the
// live row, and a value outside its width matches no row.
pub fn account_state_commitment(
    address: Field,
    nullifier_key_commitment: Field,
    account_rule_set_commitment: Field,
    account_kind: Field,
    account_revision: Field,
    receive_key_hash: Field,
) -> Field {
    pcash_hash([
        ACCOUNT_STATE_COMMITMENT_DOMAIN,
        address,
        nullifier_key_commitment,
        account_rule_set_commitment,
        account_kind,
        account_revision,
        receive_key_hash,
    ])
}

// accountRuleEntryCommitment = poseidon(ACCOUNT_RULE_ENTRY_DOMAIN,
//   applicationVkHash, configurationCommitment, commitmentBlinder).
pub fn account_rule_entry_commitment(
    application_vk_hash: Field,
    configuration_commitment: Field,
    commitment_blinder: Field,
) -> Field {
    pcash_hash([
        ACCOUNT_RULE_ENTRY_DOMAIN,
        application_vk_hash,
        configuration_commitment,
        commitment_blinder,
    ])
}

// The network-independent compare-and-swap of a user-account update: the
// account state it replaces and the one it installs. The node recomputes it
// from the live row; the update's action commitment carries it as extra data.
pub fn account_update_commitment(
    current_account_state_commitment: Field,
    new_account_state_commitment: Field,
) -> Field {
    pcash_hash([
        ACCOUNT_UPDATE_COMMITMENT_DOMAIN,
        current_account_state_commitment,
        new_account_state_commitment,
    ])
}

mod tests {
    use crate::generated::pcash_constants::{
        ACCOUNT_RULE_ENTRY_DOMAIN, ACCOUNT_STATE_COMMITMENT_DOMAIN,
    };
    use crate::primitives::hash::pcash_hash;
    use super::{account_rule_entry_commitment, account_state_commitment, account_update_commitment};

    #[test]
    fn test_account_state_commitment_matches_formula() {
        let leaf = account_state_commitment(0xabc, 0xdef, 0x123, 0, 7, 0x456);
        assert(
            leaf
                == pcash_hash(
                    [ACCOUNT_STATE_COMMITMENT_DOMAIN, 0xabc, 0xdef, 0x123, 0, 7, 0x456],
                ),
        );
        assert(leaf != account_state_commitment(0xabd, 0xdef, 0x123, 0, 7, 0x456));
        assert(leaf != account_state_commitment(0xabc, 0xdf0, 0x123, 0, 7, 0x456));
        assert(leaf != account_state_commitment(0xabc, 0xdef, 0x124, 0, 7, 0x456));
        // accountKind is committed: a smart-contract (kind 1) leaf differs from a user one.
        assert(leaf != account_state_commitment(0xabc, 0xdef, 0x123, 1, 7, 0x456));
        assert(leaf != account_state_commitment(0xabc, 0xdef, 0x123, 0, 8, 0x456));
        assert(leaf != account_state_commitment(0xabc, 0xdef, 0x123, 0, 7, 0x457));
        assert(leaf != account_state_commitment(0xabc, 0xdef, 0x123, 0, 7, 0));
    }

    #[test]
    fn test_account_rule_entry_commitment_matches_formula() {
        let entry = account_rule_entry_commitment(0x111, 0x222, 0x333);
        assert(entry == pcash_hash([ACCOUNT_RULE_ENTRY_DOMAIN, 0x111, 0x222, 0x333]));
        // Every entry field is committed independently.
        assert(entry != account_rule_entry_commitment(0x112, 0x222, 0x333));
        assert(entry != account_rule_entry_commitment(0x111, 0x223, 0x333));
        assert(entry != account_rule_entry_commitment(0x111, 0x222, 0x334));
    }

    #[test]
    fn test_account_update_commitment_binds_every_operand() {
        let update = account_update_commitment(4, 5);
        assert(update != account_update_commitment(6, 5));
        assert(update != account_update_commitment(4, 6));
    }
}

// Open an account and its selected rule under the exact Mega VK being folded.
// The account row commits the rule set the selected entry's path opens, so an
// opening describes installed authority only after its root is authenticated.
// The sponsored-transfer, asset-creation and contract-creation kernels use
// authenticate. The transfer kernel calls open_account and checks the root
// itself, because an action whose every input is DUMMY skips membership. The
// account-update kernel opens only the account row, whose current value the
// node checks through the update's account update commitment.

use crate::authorization::account::{account_rule_entry_commitment, account_state_commitment};
use crate::authorization::statement::authorization_commitment;
use crate::ledger::note::{note_nk, nullifier_key_commitment};
use crate::primitives::types::{AccountRuleMembershipWitness, MerkleWitness};
use crate::state::merkle::binary_root_from_index;

pub struct AuthorizedAccount {
    pub address: Field,
    pub nk_root: Field,
    pub account_witness: MerkleWitness,
    pub account_revision: Field,
    pub receive_key_hash: Field,
    pub configuration_commitment: Field,
    pub commitment_blinder: Field,
    pub account_rule_witness: AccountRuleMembershipWitness,
}

// An opened account: its address, which names it and owns its notes, the
// key its note nullifiers derive from, the selected rule entry, and the
// authorization commitment that entry's rule statement must name.
pub struct AccountOpening {
    pub address: Field,
    pub nk: Field,
    pub entry: Field,
    pub authorization: Field,
}

// `account_kind` is the kind the caller requires the account to be, or the
// kind it witnessed when it admits both.
pub fn authenticate(
    account: AuthorizedAccount,
    account_kind: Field,
    application_vk_hash: Field,
    account_state_root: Field,
) -> AccountOpening {
    let (root, opened) = open_account(account, account_kind, application_vk_hash);
    assert(root == account_state_root, "account must be in the account state tree");
    opened
}

// Returns the account-state root the witness path implies, and the opening.
pub fn open_account(
    account: AuthorizedAccount,
    account_kind: Field,
    application_vk_hash: Field,
) -> (Field, AccountOpening) {
    let (leaf, opened) = open_account_leaf(
        account.address,
        account.nk_root,
        account_kind,
        account.account_revision,
        account.receive_key_hash,
        application_vk_hash,
        account.configuration_commitment,
        account.commitment_blinder,
        account.account_rule_witness,
    );
    let root = binary_root_from_index(
        leaf,
        account.account_witness.leaf_index,
        account.account_witness.siblings,
    );
    (root, opened)
}

// The account-state row whose rule set the selected rule's path opens, without
// the row's position in the account tree. Returns the row commitment and the
// opening.
pub fn open_account_leaf(
    address: Field,
    nk_root: Field,
    account_kind: Field,
    account_revision: Field,
    receive_key_hash: Field,
    application_vk_hash: Field,
    configuration_commitment: Field,
    commitment_blinder: Field,
    account_rule_witness: AccountRuleMembershipWitness,
) -> (Field, AccountOpening) {
    let entry = account_rule_entry_commitment(
        application_vk_hash,
        configuration_commitment,
        commitment_blinder,
    );
    let account_rule_set_commitment = binary_root_from_index(
        entry,
        account_rule_witness.entry_index as Field,
        account_rule_witness.siblings,
    );
    let leaf = account_state_commitment(
        address,
        nullifier_key_commitment(nk_root),
        account_rule_set_commitment,
        account_kind,
        account_revision,
        receive_key_hash,
    );
    let authorization = authorization_commitment(address, configuration_commitment);
    (leaf, AccountOpening { address, nk: note_nk(nk_root), entry, authorization })
}

mod tests {
    use crate::authorization::account::{
        ACCOUNT_KIND_CONTRACT, ACCOUNT_KIND_USER, account_rule_entry_commitment,
        account_state_commitment,
    };
    use crate::authorization::statement::authorization_commitment;
    use crate::ledger::note::{note_nk, nullifier_key_commitment};
    use crate::primitives::params::{ACCOUNT_RULE_SET_DEPTH, MERKLE_DEPTH};
    use crate::primitives::types::{AccountRuleMembershipWitness, MerkleWitness};
    use crate::state::merkle::binary_root_from_index;
    use super::{authenticate, AuthorizedAccount};

    global ADDRESS: Field = 0xabc;
    global VK_HASH: Field = 0x5555;
    global CONFIGURATION: Field = 0x4444;
    global BLINDER: Field = 0x77;

    // A user account in the first leaf with one installed rule, and the
    // account-state root it implies.
    fn installed(nk_root: Field) -> (AuthorizedAccount, Field) {
        let entry = account_rule_entry_commitment(VK_HASH, CONFIGURATION, BLINDER);
        let rule_set = binary_root_from_index(entry, 0, [0; ACCOUNT_RULE_SET_DEPTH]);
        let leaf = account_state_commitment(
            ADDRESS,
            nullifier_key_commitment(nk_root),
            rule_set,
            ACCOUNT_KIND_USER,
            1,
            0,
        );
        let account = AuthorizedAccount {
            address: ADDRESS,
            nk_root,
            account_witness: MerkleWitness { leaf_index: 0, siblings: [0; MERKLE_DEPTH] },
            account_revision: 1,
            receive_key_hash: 0,
            configuration_commitment: CONFIGURATION,
            commitment_blinder: BLINDER,
            account_rule_witness: AccountRuleMembershipWitness {
                entry_index: 0,
                siblings: [0; ACCOUNT_RULE_SET_DEPTH],
            },
        };
        (account, binary_root_from_index(leaf, 0, [0; MERKLE_DEPTH]))
    }

    // A zero root is one more root: the account authenticates, and its notes
    // nullify under the key it derives.
    #[test]
    fn test_authenticates_an_account_with_a_zero_nk_root() {
        let (account, root) = installed(0);
        let opened = authenticate(account, ACCOUNT_KIND_USER, VK_HASH, root);
        assert(opened.address == ADDRESS);
        assert(opened.nk == note_nk(0));
        assert(opened.authorization == authorization_commitment(ADDRESS, CONFIGURATION));
    }

    // The account still acts only through a rule it installed: another rule
    // opens another rule set, which no account row commits.
    #[test(should_fail_with = "account must be in the account state tree")]
    fn test_a_zero_nk_root_account_still_needs_its_rule() {
        let (account, root) = installed(0);
        let _ = authenticate(account, ACCOUNT_KIND_USER, VK_HASH + 1, root);
    }

    // The row commits the rule set the selected entry's path opens, so another
    // path opens another rule set.
    #[test(should_fail_with = "account must be in the account state tree")]
    fn test_rejects_another_rule_sibling() {
        let (mut account, root) = installed(0);
        account.account_rule_witness.siblings[ACCOUNT_RULE_SET_DEPTH - 1] = 1;
        let _ = authenticate(account, ACCOUNT_KIND_USER, VK_HASH, root);
    }

    #[test(should_fail_with = "account must be in the account state tree")]
    fn test_rejects_another_rule_entry_index() {
        let (mut account, root) = installed(0);
        account.account_rule_witness.entry_index = 1;
        let _ = authenticate(account, ACCOUNT_KIND_USER, VK_HASH, root);
    }

    #[test(should_fail_with = "account must be in the account state tree")]
    fn test_rejects_a_root_the_account_does_not_commit() {
        let (mut account, root) = installed(0);
        account.nk_root = 1;
        let _ = authenticate(account, ACCOUNT_KIND_USER, VK_HASH, root);
    }

    // The kind is the caller's: a user account does not open as a contract.
    #[test(should_fail_with = "account must be in the account state tree")]
    fn test_rejects_an_account_of_another_kind() {
        let (account, root) = installed(0);
        let _ = authenticate(account, ACCOUNT_KIND_CONTRACT, VK_HASH, root);
    }
}

// The rule statement: what an account's selected rule returns to the kernel,
// [authorizationCommitment, actionCommitment, recentPcashBlockHash, eventEntry].
//
// The kernel computes the same four values from the account and rule entry it
// authenticated, the private value it built, and the role it proves, and
// requires the rule's return to equal them. Every action commitment is one
// formula over (actionDomain, pcashChainId, privateValueCommitment, extraData);
// each role has its own constructor, so an action domain is never a free input.
// Each distinct approval has its own domain. Two kernels share one only when
// the approval means the same thing to the signer and the rule's checks do not
// depend on which kernel runs.

use crate::generated::pcash_constants::{
    ACCOUNT_UPDATE_ACTION_DOMAIN, ASSET_CREATION_ACTION_DOMAIN, AUTHORIZATION_COMMITMENT_DOMAIN,
    CONTRACT_FEE_SPONSORSHIP_ACTION_DOMAIN, SPONSORED_TRANSFER_ACTION_DOMAIN,
    TRANSFER_ACTION_DOMAIN,
};
use crate::ledger::private_value::{
    private_value_commitment, PrivateValue, SLOT_CLASS_ASSET_CREATION,
};
use crate::primitives::hash::pcash_hash;

pub global RULE_STATEMENT_LENGTH: u32 = 4;

// Which account acts, named by its address, under which settings of the
// selected rule.
pub fn authorization_commitment(address: Field, configuration_commitment: Field) -> Field {
    pcash_hash(
        [AUTHORIZATION_COMMITMENT_DOMAIN, address, configuration_commitment],
    )
}

fn action_commitment(
    action_domain: Field,
    pcash_chain_id: Field,
    private_value_commitment: Field,
    extra_data: Field,
) -> Field {
    pcash_hash(
        [action_domain, pcash_chain_id, private_value_commitment, extra_data],
    )
}

// One account moves its own value: the transfer kernel.
pub fn transfer_action_commitment(pcash_chain_id: Field, private_value_commitment: Field) -> Field {
    action_commitment(
        TRANSFER_ACTION_DOMAIN,
        pcash_chain_id,
        private_value_commitment,
        0,
    )
}

// One account creates an asset and its supply: the asset-creation kernel. The
// extra data is the ID of the asset the kernel derives.
pub fn asset_creation_action_commitment(
    pcash_chain_id: Field,
    private_value_commitment: Field,
    asset_id: Field,
) -> Field {
    action_commitment(
        ASSET_CREATION_ACTION_DOMAIN,
        pcash_chain_id,
        private_value_commitment,
        asset_id,
    )
}

// A rule that opens the private value and serves both one-account kernels
// chooses between their actions by its slot classes: the asset-creation action
// for `created_asset_id` when an input is a creation marker, else the transfer
// action, which ignores `created_asset_id`.
pub fn owner_action_commitment<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    created_asset_id: Field,
) -> Field {
    let commitment = private_value_commitment(private_value);
    let mut creates_asset = false;
    for i in 0..N_IN {
        creates_asset |= private_value.input_slot_classes[i] == SLOT_CLASS_ASSET_CREATION;
    }
    if creates_asset {
        asset_creation_action_commitment(pcash_chain_id, commitment, created_asset_id)
    } else {
        transfer_action_commitment(pcash_chain_id, commitment)
    }
}

// The contract side of a sponsored transfer: the contract moves the asset and
// another account pays the native fee.
pub fn sponsored_transfer_action_commitment(
    pcash_chain_id: Field,
    private_value_commitment: Field,
) -> Field {
    action_commitment(
        SPONSORED_TRANSFER_ACTION_DOMAIN,
        pcash_chain_id,
        private_value_commitment,
        0,
    )
}

// A user account pays the native fee for one named contract: its asset action
// in a sponsored transfer, or its creation.
pub fn contract_fee_sponsorship_action_commitment(
    pcash_chain_id: Field,
    private_value_commitment: Field,
    contract_address: Field,
) -> Field {
    action_commitment(
        CONTRACT_FEE_SPONSORSHIP_ACTION_DOMAIN,
        pcash_chain_id,
        private_value_commitment,
        contract_address,
    )
}

// A user-account update together with the fee payment that funds it.
pub fn account_update_action_commitment(
    pcash_chain_id: Field,
    private_value_commitment: Field,
    account_update_commitment: Field,
) -> Field {
    action_commitment(
        ACCOUNT_UPDATE_ACTION_DOMAIN,
        pcash_chain_id,
        private_value_commitment,
        account_update_commitment,
    )
}

// A contract function that serves both the transfer and the sponsored-transfer
// role chooses between them with `fee_paid`.
pub fn contract_action_commitment(
    pcash_chain_id: Field,
    private_value_commitment: Field,
    fee_paid: bool,
) -> Field {
    if fee_paid {
        sponsored_transfer_action_commitment(pcash_chain_id, private_value_commitment)
    } else {
        transfer_action_commitment(pcash_chain_id, private_value_commitment)
    }
}

pub fn rule_statement(
    authorization_commitment: Field,
    action_commitment: Field,
    recent_pcash_block_hash: Field,
    event_entry: Field,
) -> [Field; RULE_STATEMENT_LENGTH] {
    [authorization_commitment, action_commitment, recent_pcash_block_hash, event_entry]
}

// The kernel's check of a rule's return against the four fields it computes.
pub fn assert_rule_statement(
    statement: [Field; RULE_STATEMENT_LENGTH],
    authorization_commitment: Field,
    action_commitment: Field,
    recent_pcash_block_hash: Field,
    event_entry: Field,
) {
    assert(
        statement
            == rule_statement(
                authorization_commitment,
                action_commitment,
                recent_pcash_block_hash,
                event_entry,
            ),
        "rule statement must match the kernel's statement",
    );
}

mod tests {
    use crate::generated::pcash_constants::{
        ASSET_CREATION_ACTION_DOMAIN, AUTHORIZATION_COMMITMENT_DOMAIN, TRANSFER_ACTION_DOMAIN,
    };
    use crate::ledger::private_value::{
        private_value_commitment, PrivateValue, SLOT_CLASS_APPLICATION, SLOT_CLASS_ASSET,
        SLOT_CLASS_ASSET_CREATION, SLOT_CLASS_DUMMY, SLOT_CLASS_NATIVE,
    };
    use crate::primitives::hash::pcash_hash;
    use super::{
        account_update_action_commitment, asset_creation_action_commitment,
        authorization_commitment, contract_action_commitment,
        contract_fee_sponsorship_action_commitment, owner_action_commitment,
        sponsored_transfer_action_commitment, transfer_action_commitment,
    };

    #[test]
    fn test_action_commitments_separate_roles_and_chains() {
        let transfer = transfer_action_commitment(1, 0x10);
        assert(transfer == pcash_hash([TRANSFER_ACTION_DOMAIN, 1, 0x10, 0]));
        assert(transfer != transfer_action_commitment(2, 0x10));
        let asset_creation = asset_creation_action_commitment(1, 0x10, 0x50);
        assert(asset_creation == pcash_hash([ASSET_CREATION_ACTION_DOMAIN, 1, 0x10, 0x50]));
        assert(transfer != asset_creation_action_commitment(1, 0x10, 0));
        assert(asset_creation != asset_creation_action_commitment(2, 0x10, 0x50));
        assert(asset_creation != asset_creation_action_commitment(1, 0x10, 0x51));
        assert(transfer != sponsored_transfer_action_commitment(1, 0x10));
        assert(transfer != contract_fee_sponsorship_action_commitment(1, 0x10, 0));
        assert(transfer != account_update_action_commitment(1, 0x10, 0));
        assert(contract_action_commitment(1, 0x10, false) == transfer);
        assert(
            contract_action_commitment(1, 0x10, true)
                == sponsored_transfer_action_commitment(1, 0x10),
        );
        assert(
            contract_fee_sponsorship_action_commitment(1, 0x10, 0x20)
                != contract_fee_sponsorship_action_commitment(1, 0x10, 0x21),
        );
    }

    fn private_value(input_slot_classes: [Field; 2]) -> PrivateValue<2, 1, 0> {
        let mut input_commitments = [0; 2];
        for i in 0..2 {
            if (input_slot_classes[i] == SLOT_CLASS_NATIVE)
                | (input_slot_classes[i] == SLOT_CLASS_ASSET) {
                input_commitments[i] = 0x30 + i as Field;
            }
        }
        PrivateValue {
            open_fee_amount: 0,
            issuance_owner_commitment: 0,
            not_before_timestamp: 0,
            valid_until_timestamp: 1000,
            carrier_context_hash: 0,
            asset_burn_amount: 0,
            delivery_commitment: 0,
            input_slot_classes,
            input_commitments,
            nullifiers: [0x21, 0x22],
            output_slot_classes: [SLOT_CLASS_ASSET],
            output_body_commitments: [0x40],
        }
    }

    // A creation marker selects the asset-creation action for the created
    // asset; every other input class leaves the transfer action.
    #[test]
    fn test_owner_action_selects_the_asset_creation_action_by_creation_marker() {
        let creation = private_value([SLOT_CLASS_NATIVE, SLOT_CLASS_ASSET_CREATION]);
        assert(
            owner_action_commitment(1, creation, 0x50)
                == asset_creation_action_commitment(1, private_value_commitment(creation), 0x50),
        );
        let other_classes =
            [SLOT_CLASS_DUMMY, SLOT_CLASS_NATIVE, SLOT_CLASS_ASSET, SLOT_CLASS_APPLICATION];
        for class in other_classes {
            let transfer = private_value([SLOT_CLASS_NATIVE, class]);
            assert(
                owner_action_commitment(1, transfer, 0x50)
                    == transfer_action_commitment(1, private_value_commitment(transfer)),
            );
        }
    }

    #[test]
    fn test_authorization_commitment_binds_address_and_configuration() {
        let commitment = authorization_commitment(0x1, 0x2);
        assert(commitment == pcash_hash([AUTHORIZATION_COMMITMENT_DOMAIN, 0x1, 0x2]));
        assert(commitment != authorization_commitment(0x2, 0x1));
    }
}

// Applications attest to a transaction without authorizing its ledger transition.
use crate::generated::pcash_constants::{EVENT_DOMAIN, EVENT_ENTRY_DOMAIN};
use crate::primitives::hash::pcash_hash;
use crate::recursion::{AppVerificationKey, verify_next_app};

pub global EVENT_STATEMENT_LENGTH: u32 = 3;

pub fn events_commitment(entry: Field, salt: Field) -> Field {
    pcash_hash([EVENT_DOMAIN, entry, salt])
}

pub fn event_entry(application_vk_hash: Field, event: Field) -> Field {
    pcash_hash([EVENT_ENTRY_DOMAIN, application_vk_hash, event])
}

pub fn event_statement(
    action_commitment: Field,
    recent_pcash_block_hash: Field,
    event: Field,
) -> [Field; EVENT_STATEMENT_LENGTH] {
    [action_commitment, recent_pcash_block_hash, event]
}

pub fn verify_event(
    statement: [Field; EVENT_STATEMENT_LENGTH],
    vk: AppVerificationKey,
    action_commitment: Field,
    recent_pcash_block_hash: Field,
) -> Field {
    verify_next_app(vk);
    assert(statement[0] == action_commitment, "event must bind the transaction action");
    assert(statement[1] == recent_pcash_block_hash, "event must bind the transaction anchor");
    event_entry(vk.hash, statement[2])
}

mod tests {
    use crate::primitives::hash::pcash_hash;
    use crate::recursion::{AppVerificationKey, MEGA_APP_VK_LENGTH_IN_FIELDS};
    use super::{event_entry, events_commitment, verify_event};

    fn vk() -> AppVerificationKey {
        let key = [7; MEGA_APP_VK_LENGTH_IN_FIELDS];
        AppVerificationKey { key, hash: pcash_hash(key) }
    }

    #[test]
    fn event_binds_application_and_salt() {
        let entry = event_entry(1, 2);
        assert(entry != event_entry(2, 2));
        assert(entry != event_entry(1, 3));
        assert(events_commitment(entry, 3) != events_commitment(entry, 4));
        assert(events_commitment(entry, 3) != events_commitment(event_entry(2, 2), 3));
        assert(verify_event([10, 20, 30], vk(), 10, 20) == event_entry(vk().hash, 30));
        assert(verify_event([10, 20, 0], vk(), 10, 20) == event_entry(vk().hash, 0));
    }

    #[test(should_fail_with = "event must bind the transaction action")]
    fn rejects_another_action() {
        let _ = verify_event([11, 20, 30], vk(), 10, 20);
    }

    #[test(should_fail_with = "event must bind the transaction anchor")]
    fn rejects_another_anchor() {
        let _ = verify_event([10, 21, 30], vk(), 10, 20);
    }

}

