    // with a nonzero amount is an asset note; the rest are padding.
    fn fixture<let N_IN: u32, let N_OUT: u32>(amounts: [Field; N_OUT]) -> Fixture<N_IN, N_OUT> {
        let mut input_slot_classes = [SLOT_CLASS_DUMMY; N_IN];
        input_slot_classes[0] = SLOT_CLASS_ASSET_CREATION;
        let mut output_slot_classes = [SLOT_CLASS_DUMMY; N_OUT];
        let mut owners = [0; N_OUT];
        let mut secrets = [0; N_OUT];
        for i in 0..N_OUT {
            if amounts[i] != 0 {
                output_slot_classes[i] = SLOT_CLASS_ASSET;
                owners[i] = TEST_OWNER + i as Field;
            } else {
                secrets[i] = (i + 1) as Field;
            }
        }
        Fixture {
            choices: PrivateValueChoices {
                open_fee_amount: 0,
                issuance_owner_commitment: 0,
                not_before_timestamp: 0,
                valid_until_timestamp: 1,
                carrier_context_hash: 0,
                asset_burn_amount: 0,
                delivery_commitment: 0,
                input_slot_classes,
                output_slot_classes,
            },
            owners,
            secrets,
            amounts,
            native_inputs: [
                InputNoteWitness {
                    output_index: 0,
                    note_secret: 0,
                    amount: 0,
                    siblings: [0; MERKLE_DEPTH],
                }; N_IN
            ],
            replay_ids: [0; N_IN],
            output_root: 0,
        }
    }

    fn one_output() -> Fixture<4, 5> {
        fixture([TEST_SUPPLY, 0, 0, 0, 0])
    }

    fn build<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
        f: Fixture<N_IN, N_OUT>,
        supply: Field,
        secret: Field,
    ) -> (PrivateValue<N_IN, N_OUT, SHAPE>, Field, Field) {
        fixed_supply(
            f.choices,
            TEST_METADATA,
            supply,
            secret,
            ACCOUNT,
            f.output_root,
            TEST_SEED,
            f.native_inputs,
            f.replay_ids,
            f.owners,
            f.secrets,
            f.amounts,
        )
    }

    fn run<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
        f: Fixture<N_IN, N_OUT>,
        supply: Field,
        secret: Field,
    ) -> PrivateValue<N_IN, N_OUT, SHAPE> {
        let (private_value, _, _) = build(f, supply, secret);
        private_value
    }

    #[test]
    fn test_fixed_supply_accepts_complete_initial_supply_in_one_output() {
        let _: PrivateValue<4, 5, 0> = run(one_output(), TEST_SUPPLY, TEST_SECRET);
    }

    #[test]
    fn test_fixed_supply_accepts_valid_split_across_outputs() {
        let _: PrivateValue<4, 5, 0> = run(
            fixture([600_000, 400_000, 0, 0, 0]),
            TEST_SUPPLY,
            TEST_SECRET,
        );
    }

    #[test]
    fn test_fixed_supply_accepts_the_asset_law_maximum_in_the_large_shape() {
        let mut amounts = [0; 32];
        for i in 27..32 {
            amounts[i] = MAX_AMOUNT;
        }
        let _: PrivateValue<32, 32, 1> = run(fixture(amounts), MAX_ASSET_SUPPLY, TEST_SECRET);
    }

    // The marker and every asset output derive from the asset the secret
    // defines, whose ID the relation returns. Another secret defines another
    // asset with another marker.
    #[test]
    fn test_fixed_supply_derives_the_marker_and_outputs_from_the_asset() {
        let (value, _, asset_id): (PrivateValue<4, 5, 0>, Field, Field) =
            build(one_output(), TEST_SUPPLY, TEST_SECRET);
        assert(asset_id == asset_id_of(TEST_SUPPLY));
        assert(value.nullifiers[0] == asset_creation_marker(asset_id, TEST_SECRET));
        assert(
            value.output_body_commitments[0]
                == note_body_commitment(TEST_OWNER, asset_id, TEST_SUPPLY),
        );
        let other: PrivateValue<4, 5, 0> = run(one_output(), TEST_SUPPLY, TEST_SECRET + 1);
        assert(other.nullifiers[0] != value.nullifiers[0]);
        assert(other.output_body_commitments[0] != value.output_body_commitments[0]);
    }

    // A native output is no part of the supply; the creating account's native
    // notes fund it.
    #[test]
    fn test_fixed_supply_does_not_count_a_native_output_toward_supply() {
        let mut f = one_output();
        let note = Note { owner: ACCOUNT.address, note_secret: 0x5ec, asset_id: 0, amount: 7 };
        let leaf = full_output_commitment(note, 0);
        f.output_root = binary_root_from_index(leaf, 0, [0; MERKLE_DEPTH]);
        f.choices.input_slot_classes[1] = SLOT_CLASS_NATIVE;
        f.native_inputs[1] = InputNoteWitness {
            output_index: 0,
            note_secret: 0x5ec,
            amount: 7,
            siblings: [0; MERKLE_DEPTH],
        };
        f.choices.output_slot_classes[1] = SLOT_CLASS_NATIVE;
        f.owners[1] = TEST_OWNER;
        f.amounts[1] = 7;
        let value: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
        assert(value.input_commitments[1] == leaf);
        assert(value.nullifiers[1] == nullifier(leaf, ACCOUNT.nk, 0x5ec));
    }

    #[test(should_fail_with = "native inputs must equal native outputs plus the open fee")]
    fn test_fixed_supply_rejects_an_unfunded_native_output() {
        let mut f = one_output();
        f.choices.output_slot_classes[1] = SLOT_CLASS_NATIVE;
        f.owners[1] = TEST_OWNER;
        f.amounts[1] = 7;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail_with = "asset creation must carry exactly one creation marker")]
    fn test_fixed_supply_rejects_missing_creation_marker() {
        let mut f = one_output();
        f.choices.input_slot_classes[0] = SLOT_CLASS_DUMMY;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail_with = "asset creation must carry exactly one creation marker")]
    fn test_fixed_supply_rejects_duplicate_creation_marker() {
        let mut f = one_output();
        f.choices.input_slot_classes[1] = SLOT_CLASS_ASSET_CREATION;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail_with = "asset creation input class must be dummy, native, asset creation, or application")]
    fn test_fixed_supply_rejects_asset_input() {
        let mut f = one_output();
        f.choices.input_slot_classes[1] = SLOT_CLASS_ASSET;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    fn with_marker(replay_id: Field) -> Fixture<4, 5> {
        let mut f = one_output();
        f.choices.input_slot_classes[1] = SLOT_CLASS_APPLICATION;
        f.replay_ids[1] = replay_id;
        f
    }

    // The marker is the creating account's, scoped to its selected rule entry,
    // exactly as in a transfer.
    #[test]
    fn test_fixed_supply_derives_the_application_marker_of_the_creating_account() {
        let value: PrivateValue<4, 5, 0> = run(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET);
        assert(value.nullifiers[1] == application_marker(ACCOUNT, 0x7e));
        assert(value.nullifiers[1] == application_nullifier(ACCOUNT.address, ACCOUNT.entry, 0x7e));
    }

    // A rule approved the private value with its marker; one built from
    // another replay ID is another private value, so the rule's statement does
    // not match it.
    #[test(should_fail_with = "rule statement must match the kernel's statement")]
    fn test_fixed_supply_rejects_a_marker_the_rule_did_not_approve() {
        let (_, approved, asset_id): (PrivateValue<4, 5, 0>, Field, Field) =
            build(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET);
        let (_, built, _): (PrivateValue<4, 5, 0>, Field, Field) =
            build(with_marker(0x7f), TEST_SUPPLY, TEST_SECRET);
        assert_rule_statement(
            [1, asset_creation_action_commitment(7, approved, asset_id), 2, 0],
            1,
            asset_creation_action_commitment(7, built, asset_id),
            2,
            0,
        );
    }

    #[test]
    fn test_fixed_supply_accepts_replay_id_zero() {
        let value: PrivateValue<4, 5, 0> = run(with_marker(0), TEST_SUPPLY, TEST_SECRET);
        assert(value.nullifiers[1] == application_marker(ACCOUNT, 0));
    }

    // One fact authorizes at most one asset creation per account and rule
    // entry: another asset secret creates another asset under the same
    // marker, which the node's nullifier uniqueness then rejects.
    #[test]
    fn test_fixed_supply_application_marker_is_the_same_for_another_asset() {
        let first: PrivateValue<4, 5, 0> = run(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET);
        let second: PrivateValue<4, 5, 0> = run(with_marker(0x7e), TEST_SUPPLY, TEST_SECRET + 1);
        assert(first.nullifiers[0] != second.nullifiers[0]);
        assert(first.nullifiers[1] == second.nullifiers[1]);
    }

    #[test(should_fail_with = "asset burn amount must be zero")]
    fn test_fixed_supply_rejects_nonzero_burn() {
        let mut f = one_output();
        f.choices.asset_burn_amount = 1;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_underminting() {
        let _: PrivateValue<4, 5, 0> = run(
            fixture([TEST_SUPPLY - 1, 0, 0, 0, 0]),
            TEST_SUPPLY,
            TEST_SECRET,
        );
    }

    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_overminting() {
        let _: PrivateValue<4, 5, 0> = run(
            fixture([TEST_SUPPLY + 1, 0, 0, 0, 0]),
            TEST_SUPPLY,
            TEST_SECRET,
        );
    }

    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_no_asset_outputs() {
        let _: PrivateValue<4, 5, 0> = run(fixture([0; 5]), TEST_SUPPLY, TEST_SECRET);
    }

    // A zero supply creates the asset and its marker but no note.
    #[test]
    fn test_fixed_supply_accepts_a_zero_supply_without_asset_outputs() {
        let (value, _, asset_id): (PrivateValue<4, 5, 0>, Field, Field) =
            build(fixture([0; 5]), 0, TEST_SECRET);
        assert(asset_id == asset_id_of(0));
        assert(value.nullifiers[0] == asset_creation_marker(asset_id, TEST_SECRET));
        assert(value.output_slot_classes == [SLOT_CLASS_DUMMY; 5]);
    }

    // Real outputs are positive, so a zero supply cannot mint a unit.
    #[test(should_fail_with = "asset outputs must sum to the initial supply")]
    fn test_fixed_supply_rejects_a_positive_asset_output_under_a_zero_supply() {
        let _: PrivateValue<4, 5, 0> = run(fixture([1, 0, 0, 0, 0]), 0, TEST_SECRET);
    }

    #[test(should_fail_with = "real output amount must be nonzero")]
    fn test_fixed_supply_rejects_zero_amount_asset_output() {
        let mut f = one_output();
        f.choices.output_slot_classes[1] = SLOT_CLASS_ASSET;
        f.owners[1] = TEST_OWNER;
        let _: PrivateValue<4, 5, 0> = run(f, TEST_SUPPLY, TEST_SECRET);
    }

    #[test(should_fail)]
    fn test_fixed_supply_rejects_asset_output_above_the_note_amount_range() {
        let supply = MAX_AMOUNT + 1;
        let _: PrivateValue<4, 5, 0> = run(fixture([supply, 0, 0, 0, 0]), supply, TEST_SECRET);
    }
}

// Shared S/L relation for a CONTRACT asset action sponsored by a USER account.
//
// The primary account moves the asset and owns every APPLICATION marker. A
// distinct fee-payer account contributes native PCASH for the open fee and
// optional private relay output, and receives at most one change note. Nothing
// else about the fee payer is at stake: their exposure is bounded by their own
// native contribution, and what the open fee and relay note leave returns to
// their address. The authorizing rule binds the relay note's amount and
// owner and which change opening it accepts — the reference rule requires the
// owner's derived change secret — because only that rule knows what the fee
// payer approved and which secrets they hold.
//
// The two authorizing accounts have fixed roles: the primary CONTRACT controls
// the asset action; the sponsoring USER funds the open fee or private relay
// output. This is not general multi-owner settlement. Private slot classes
// assign those roles without a per-slot owner field or a public sponsorship-mode
// indicator.
//
// This is a separate CHONK protocol kernel because it consumes two installed
// authorization applications rather than the transfer kernel's one.

use crate::authorization::account::{ACCOUNT_KIND_CONTRACT, ACCOUNT_KIND_USER};
use crate::authorization::authentication::{authenticate, AuthorizedAccount};
use crate::authorization::statement::{
    assert_rule_statement, contract_fee_sponsorship_action_commitment, RULE_STATEMENT_LENGTH,
    sponsored_transfer_action_commitment,
};
use crate::events::{EVENT_STATEMENT_LENGTH, events_commitment, verify_event};
use crate::ledger::fee_payment::{
    assert_native_fee_conservation, native_change_outputs, NativeChange, NativeRelayOutput,
};
use crate::ledger::opening::{open_transfer_inputs, open_value_state};
use crate::ledger::private_value::{
    PrivateValue, PrivateValueChoices, SLOT_CLASS_ASSET, transaction_statement,
};
use crate::ledger::section::{assert_asset_conservation, build_private_value, output_bodies};
use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, STATE_TREE_DEPTH};
use crate::primitives::types::InputNoteWitness;
use crate::recursion::{AppVerificationKey, verify_first_app, verify_next_app};

pub fn sponsored_transfer<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    choices: PrivateValueChoices<N_IN, N_OUT>,
    output_owner_commitments: [Field; N_OUT],
    output_dummy_secrets: [Field; N_OUT],
    asset_output_amounts: [Field; N_OUT],
    // The fee payer's change note, if any. Its secret is theirs to choose: the
    // change returns to a real party, not to a contract that later provers must
    // be able to reconstruct.
    native_change: NativeChange,
    native_relay_output: NativeRelayOutput,
    asset_id: Field,
    dummy_input_seed: Field,
    replay_ids: [Field; N_IN],
    block_header_state_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    output_root: Field,
    state_output_siblings: [Field; STATE_TREE_DEPTH],
    account_state_root: Field,
    state_account_siblings: [Field; STATE_TREE_DEPTH],
    primary: AuthorizedAccount,
    fee_payer: AuthorizedAccount,
    owner_inputs: [InputNoteWitness; N_IN],
    primary_statement: [Field; RULE_STATEMENT_LENGTH],
    primary_vk: AppVerificationKey,
    fee_statement: [Field; RULE_STATEMENT_LENGTH],
    fee_vk: AppVerificationKey,
    event_statement: [Field; EVENT_STATEMENT_LENGTH],
    event_application_vk: AppVerificationKey,
    event_salt: Field,
) -> [Field; N_IN + N_OUT + 9] {
    open_value_state(
        recent_pcash_block_hash,
        block_header_state_siblings,
        output_root,
        state_output_siblings,
        account_state_root,
        state_account_siblings,
    );

    // Targeted sponsorship only: a User Account pays the fee for a Contract
    // Account's action. User-to-user sponsorship is excluded from this relation.
    // Both kinds open under one canonical snapshot, which contains one account
    // per address. Their distinct kinds therefore also make their identities distinct.
    let primary_account = authenticate(
        primary,
        ACCOUNT_KIND_CONTRACT,
        primary_vk.hash,
        account_state_root,
    );
    let fee_account = authenticate(
        fee_payer,
        ACCOUNT_KIND_USER,
        fee_vk.hash,
        account_state_root,
    );

    let inputs = open_transfer_inputs(
        choices.input_slot_classes,
        primary_account,
        fee_account,
        output_root,
        asset_id,
        dummy_input_seed,
        owner_inputs,
        replay_ids,
    );
    assert(inputs.asset_amount != 0, "sponsored transfer must spend an asset input");
    assert(inputs.native_amount != 0, "sponsored transfer must spend a native input");

    // --- outputs ---------------------------------------------------------------
    // Native outputs are payer change and, optionally, one private relay note.
    // Asset outputs carry the witnessed asset amounts.
    let (owners, native_amounts) = native_change_outputs(
        choices.output_slot_classes,
        output_owner_commitments,
        fee_account.address,
        native_change,
        native_relay_output,
    );
    let mut output_amounts = native_amounts;
    for i in 0..N_OUT {
        if choices.output_slot_classes[i] == SLOT_CLASS_ASSET {
            output_amounts[i] = asset_output_amounts[i];
        }
    }
    let bodies = output_bodies(
        choices.output_slot_classes,
        asset_id,
        owners,
        output_dummy_secrets,
        output_amounts,
    );

    // --- conservation ----------------------------------------------------------
    assert_asset_conservation(
        inputs.asset_amount,
        choices.output_slot_classes,
        output_amounts,
        choices.asset_burn_amount,
    );
    assert_native_fee_conservation(
        inputs.native_amount,
        choices.open_fee_amount,
        native_change.amount,
        native_relay_output.amount,
    );

    // --- the two authorizations -------------------------------------------------
    let (private_value, commitment): (PrivateValue<N_IN, N_OUT, SHAPE>, Field) =
        build_private_value(choices, inputs.input_commitments, inputs.nullifiers, bodies);
    // The two roles approve the same private value under different domains,
    // so neither approval reads as the other, nor as a one-account transfer.
    // The sponsor's action names the authenticated contract it pays for.
    let action = sponsored_transfer_action_commitment(pcash_chain_id, commitment);
    verify_first_app(primary_vk);
    verify_next_app(fee_vk);
    let entry = verify_event(
        event_statement,
        event_application_vk,
        action,
        recent_pcash_block_hash,
    );
    assert_rule_statement(
        primary_statement,
        primary_account.authorization,
        action,
        recent_pcash_block_hash,
        entry,
    );
    assert_rule_statement(
        fee_statement,
        fee_account.authorization,
        contract_fee_sponsorship_action_commitment(pcash_chain_id, commitment, primary.address),
        recent_pcash_block_hash,
        entry,
    );

    transaction_statement(
        pcash_chain_id,
        recent_pcash_block_hash,
        private_value,
        events_commitment(entry, event_salt),
    )
}

// The transfer kernel: one account's private-value action. The selected rule is
// the first application circuit and the transaction's event application is the
// second; the rule's private statement is linked through the databus.
// Historical account membership is required unless every input is DUMMY.
// All-dummy actions open a supplied rule set, not installed account authority.
// Asset creation and sponsored transfer use their own protocol
// kernels and converge on the same private-value hiding kernel.

use crate::authorization::authentication::{AuthorizedAccount, open_account};
use crate::authorization::statement::{
    assert_rule_statement, RULE_STATEMENT_LENGTH, transfer_action_commitment,
};
use crate::events::{EVENT_STATEMENT_LENGTH, events_commitment, verify_event};
use crate::ledger::opening::{open_transfer_inputs, open_value_state};
use crate::ledger::private_value::{
    PrivateValue, PrivateValueChoices, SLOT_CLASS_DUMMY, transaction_statement,
};
use crate::ledger::section::{
    assert_asset_conservation, assert_native_conservation, build_private_value, output_bodies,
};
use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, STATE_TREE_DEPTH};
use crate::primitives::types::InputNoteWitness;
use crate::recursion::{AppVerificationKey, verify_first_app};

pub fn transfer<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    choices: PrivateValueChoices<N_IN, N_OUT>,
    output_owner_commitments: [Field; N_OUT],
    output_dummy_secrets: [Field; N_OUT],
    output_amounts: [Field; N_OUT],
    asset_id: Field,
    dummy_input_seed: Field,
    // Rule-defined replay identity per APPLICATION slot; ignored otherwise.
    replay_ids: [Field; N_IN],
    block_header_state_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    output_root: Field,
    state_output_siblings: [Field; STATE_TREE_DEPTH],
    account_state_root: Field,
    state_account_siblings: [Field; STATE_TREE_DEPTH],
    account: AuthorizedAccount,
    // The transfer kernel acts for a user or a contract account.
    account_kind: Field,
    owner_inputs: [InputNoteWitness; N_IN],
    rule_statement: [Field; RULE_STATEMENT_LENGTH],
    authorization_vk: AppVerificationKey,
    event_statement: [Field; EVENT_STATEMENT_LENGTH],
    event_application_vk: AppVerificationKey,
    event_salt: Field,
) -> [Field; N_IN + N_OUT + 9] {
    open_value_state(
        recent_pcash_block_hash,
        block_header_state_siblings,
        output_root,
        state_output_siblings,
        account_state_root,
        state_account_siblings,
    );

    let (account_root, opening) = open_account(account, account_kind, authorization_vk.hash);
    let mut all_inputs_dummy = true;
    for i in 0..N_IN {
        all_inputs_dummy &= choices.input_slot_classes[i] == SLOT_CLASS_DUMMY;
    }
    assert(
        all_inputs_dummy | (account_root == account_state_root),
        "account must be in the account state tree",
    );

    // APPLICATION slots require installed account membership above, even when
    // no note is spent. Positive real outputs still require conserved inputs.
    let inputs = open_transfer_inputs(
        choices.input_slot_classes,
        opening,
        opening,
        output_root,
        asset_id,
        dummy_input_seed,
        owner_inputs,
        replay_ids,
    );
    let bodies = output_bodies(
        choices.output_slot_classes,
        asset_id,
        output_owner_commitments,
        output_dummy_secrets,
        output_amounts,
    );
    assert_native_conservation(
        inputs.native_amount,
        choices.output_slot_classes,
        output_amounts,
        choices.open_fee_amount,
    );
    assert_asset_conservation(
        inputs.asset_amount,
        choices.output_slot_classes,
        output_amounts,
        choices.asset_burn_amount,
    );

    let (private_value, commitment): (PrivateValue<N_IN, N_OUT, SHAPE>, Field) =
        build_private_value(choices, inputs.input_commitments, inputs.nullifiers, bodies);
    let action = transfer_action_commitment(pcash_chain_id, commitment);
    verify_first_app(authorization_vk);
    let entry = verify_event(
        event_statement,
        event_application_vk,
        action,
        recent_pcash_block_hash,
    );
    assert_rule_statement(
        rule_statement,
        opening.authorization,
        action,
        recent_pcash_block_hash,
        entry,
    );

    transaction_statement(
        pcash_chain_id,
        recent_pcash_block_hash,
        private_value,
        events_commitment(entry, event_salt),
    )
}

// The ledger rules shared by every proof-carrying transaction type: notes, the
// private value and its commitment, the private-value section, input openings,
// assets, and the native fee relation.
pub mod note;
pub mod opening;
pub mod asset;
pub mod private_value;
pub mod section;
pub mod fee_payment;

// Fixed commitments for the protocol-owned standard fungible-asset relations.
// Nonzero assets have one transfer/burn law and one fixed, one-shot creation.

use crate::generated::pcash_constants::{
    ASSET_CREATION_MARKER_DOMAIN, ASSET_ID_DOMAIN, ASSET_SECRET_COMMITMENT_DOMAIN,
};
use crate::primitives::hash::pcash_hash;
use crate::primitives::params::MAX_ASSET_SUPPLY;
use crate::primitives::range::assert_asset_aggregate;

pub fn asset_secret_commitment(asset_secret: Field) -> Field {
    pcash_hash([ASSET_SECRET_COMMITMENT_DOMAIN, asset_secret])
}

pub fn standard_fungible_asset_id(
    metadata_commitment: Field,
    initial_supply: Field,
    asset_secret_commitment: Field,
) -> Field {
    assert_asset_aggregate(initial_supply);
    // The asset law is independent of the selected transaction capacity.
    assert_asset_aggregate(MAX_ASSET_SUPPLY - initial_supply);
    pcash_hash(
        [ASSET_ID_DOMAIN, metadata_commitment, initial_supply, asset_secret_commitment],
    )
}

// The asset ID fixes the asset secret through its commitment, so the
// marker is one-shot per asset.
pub fn asset_creation_marker(asset_id: Field, asset_secret: Field) -> Field {
    pcash_hash([ASSET_CREATION_MARKER_DOMAIN, asset_id, asset_secret])
}

mod tests {
    use crate::primitives::params::MAX_ASSET_SUPPLY;
    use super::{asset_creation_marker, asset_secret_commitment, standard_fungible_asset_id};

    #[test]
    fn test_asset_id_and_creation_marker_domains_are_disjoint() {
        let secret_commitment = asset_secret_commitment(0x123);
        let id = standard_fungible_asset_id(0x789, 1_000_000, secret_commitment);
        assert(id != asset_creation_marker(id, 0x789));
    }

    #[test]
    fn test_asset_id_binds_every_field() {
        let secret_commitment = asset_secret_commitment(0x123);
        let base = standard_fungible_asset_id(0x789, 1_000_000, secret_commitment);
        assert(base != standard_fungible_asset_id(0x790, 1_000_000, secret_commitment));
        assert(base != standard_fungible_asset_id(0x789, 1_000_001, secret_commitment));
        assert(base != standard_fungible_asset_id(0x789, 1_000_000, secret_commitment + 1));
    }

    // Zero is an ordinary definition value: no metadata, no supply, or a
    // secret anyone can guess. A zero supply admits no positive asset output.
    #[test]
    fn test_asset_id_accepts_zero_definition_fields() {
        let id = standard_fungible_asset_id(0, 0, asset_secret_commitment(0));
        assert(id != 0);
        assert(id != standard_fungible_asset_id(0, 1, asset_secret_commitment(0)));
    }

    #[test]
    fn test_initial_supply_accepts_asset_law_maximum() {
        let _ = standard_fungible_asset_id(2, MAX_ASSET_SUPPLY, 3);
    }

    #[test(should_fail)]
    fn test_initial_supply_rejects_more_than_the_asset_law_maximum() {
        let _ = standard_fungible_asset_id(2, MAX_ASSET_SUPPLY + 1, 3);
    }
}

// A native-only account action: one account's native notes fund the open
// fee, an optional private relay output, and at most one change note.
//
// This is the value relation of every fee-bearing account action. A user
// account update funds its own fee this way, and a sponsored contract-account
// creation is funded this way by the sponsor. Both build the same private value
// as a type-0 transaction, and the node checks their fee section as it checks
// one. The section does not post issuanceOwnerCommitment: the node supplies
// zero there, and the action earns no issuance.
//
// The change secret is a free witness: change returns to a real party who
// keeps the secret, and the authorizing rule binds whichever opening it
// approved. Zero fee with every slot dummy is a valid degenerate payment.

use crate::authorization::authentication::AccountOpening;
use crate::ledger::note::{dummy_nullifier, owner_commitment};
use crate::ledger::opening::{open_native_notes, OpenedInputs};
use crate::ledger::private_value::{
    PrivateValue, PrivateValueChoices, SLOT_CLASS_DUMMY, SLOT_CLASS_NATIVE,
};
use crate::ledger::section::{build_private_value, output_bodies};
use crate::primitives::types::InputNoteWitness;

pub struct NativeChange {
    pub slot: u32,
    pub secret: Field,
    pub amount: Field,
}

pub struct NativeRelayOutput {
    pub slot: u32,
    pub amount: Field,
}

/// The output owners and amounts of the payer's change note and the optional
/// private relay note. A nonzero change or relay amount lands in its own
/// NATIVE slot, and change opens to the payer's address under the declared
/// secret; every other output keeps its witnessed owner and a zero amount.
///
/// The caller passes the result to output_bodies, which provides the nonzero
/// and range checks: it rejects a real output whose amount is zero or wider
/// than 128 bits. Every NATIVE output is therefore the change or the relay
/// note, and both amounts are bounded. With a zero asset ID, output_bodies also
/// rejects an ASSET output.
pub fn native_change_outputs<let N_OUT: u32>(
    output_slot_classes: [Field; N_OUT],
    output_owner_commitments: [Field; N_OUT],
    payer_address: Field,
    change: NativeChange,
    relay: NativeRelayOutput,
) -> ([Field; N_OUT], [Field; N_OUT]) {
    if relay.amount != 0 {
        assert(relay.slot < N_OUT, "relay slot must be an output slot");
        if change.amount != 0 {
            assert(relay.slot != change.slot, "relay and change slots must differ");
        }
        assert(
            output_slot_classes[relay.slot] == SLOT_CLASS_NATIVE,
            "relay slot must hold a native output",
        );
    }
    if change.amount != 0 {
        assert(change.slot < N_OUT, "change slot must be an output slot");
        assert(
            output_slot_classes[change.slot] == SLOT_CLASS_NATIVE,
            "change slot must hold a native output",
        );
    }
    let change_owner = owner_commitment(payer_address, change.secret);
    let mut owners = output_owner_commitments;
    let mut amounts = [0; N_OUT];
    for i in 0..N_OUT {
        let is_native = output_slot_classes[i] == SLOT_CLASS_NATIVE;
        if is_native & (i == change.slot) {
            amounts[i] = change.amount;
            if change.amount != 0 {
                owners[i] = change_owner;
            }
        }
        if (relay.amount != 0) & is_native & (i == relay.slot) {
            amounts[i] = relay.amount;
        }
    }
    (owners, amounts)
}

/// A fee payment's inputs: NATIVE notes of the payer, and DUMMY padding.
fn open_fee_payment_inputs<let N_IN: u32>(
    input_slot_classes: [Field; N_IN],
    payer: AccountOpening,
    output_root: Field,
    dummy_input_seed: Field,
    native_inputs: [InputNoteWitness; N_IN],
) -> OpenedInputs<N_IN> {
    let mut inputs = open_native_notes(input_slot_classes, payer, output_root, native_inputs);
    for i in 0..N_IN {
        let class = input_slot_classes[i];
        if class == SLOT_CLASS_DUMMY {
            inputs.nullifiers[i] = dummy_nullifier(dummy_input_seed, i as Field);
        } else {
            assert(class == SLOT_CLASS_NATIVE, "fee payment input must be native or dummy");
        }
    }
    inputs
}

pub fn assert_native_fee_conservation(
    native_sum_in: Field,
    open_fee_amount: Field,
    change_amount: Field,
    relay_amount: Field,
) {
    assert(
        native_sum_in == open_fee_amount + change_amount + relay_amount,
        "native inputs must equal native outputs plus the open fee",
    );
}

/// The complete native fee-payment relation for one payer. Returns the private
/// value and its commitment.
pub fn native_fee_payment<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    choices: PrivateValueChoices<N_IN, N_OUT>,
    payer: AccountOpening,
    output_root: Field,
    native_inputs: [InputNoteWitness; N_IN],
    dummy_input_seed: Field,
    output_owner_commitments: [Field; N_OUT],
    output_dummy_secrets: [Field; N_OUT],
    change: NativeChange,
    relay: NativeRelayOutput,
) -> (PrivateValue<N_IN, N_OUT, SHAPE>, Field) {
    let inputs = open_fee_payment_inputs(
        choices.input_slot_classes,
        payer,
        output_root,
        dummy_input_seed,
        native_inputs,
    );
    let (owners, amounts) = native_change_outputs(
        choices.output_slot_classes,
        output_owner_commitments,
        payer.address,
        change,
        relay,
    );
    let bodies = output_bodies(
        choices.output_slot_classes,
        0,
        owners,
        output_dummy_secrets,
        amounts,
    );
    assert(choices.asset_burn_amount == 0, "asset burn amount must be zero");
    assert_native_fee_conservation(
        inputs.native_amount,
        choices.open_fee_amount,
        change.amount,
        relay.amount,
    );
    build_private_value(choices, inputs.input_commitments, inputs.nullifiers, bodies)
}

