// The carrier context a transaction can require: a kind, the address that
// vouches for the carrier, and context bytes. An Inbox transaction's is its
// sender with an empty context; a `PcashBatch` event's is its emitter and its
// `context`. The node compares the carrying carrier's hash with the one a
// transaction states; a rule that cares recomputes it here from the bytes it
// pins and leaves the rest as witnesses.

use crate::generated::pcash_constants::CARRIER_CONTEXT_DOMAIN;
use crate::primitives::hash::pcash_hash;

pub global CARRIER_KIND_INBOX: Field = 0;
pub global CARRIER_KIND_EVENT: Field = 1;

// Hash inputs before the context chunks: domain, kind, address, context length.
global HEADER_INPUTS: u32 = 4;
// A context hash carries at least eight chunk slots, as a log's data does
// (§7.2).
global MIN_CHUNKS: u32 = 8;
global BYTES_PER_CHUNK: u32 = 16;

// poseidon(CARRIER_CONTEXT_DOMAIN, kind, address, N, chunk_0, ..., chunk_(m-1))
// with m = max(8, ceil(N / 16)): the N-byte context in 16-byte big-endian
// chunks, the last the integer of its own bytes, and zero slots past them.
// `kind` and `address` enter as given: a value outside its width equals no
// carrier's hash.
pub fn carrier_context_hash<let N: u32>(kind: Field, address: Field, context: [u8; N]) -> Field {
    if N < MIN_CHUNKS * BYTES_PER_CHUNK {
        chunked_hash::<N, MIN_CHUNKS>(kind, address, context)
    } else {
        chunked_hash::<N, (N + BYTES_PER_CHUNK - 1) / BYTES_PER_CHUNK>(kind, address, context)
    }
}

// The hash over M chunk slots, which hold the N context bytes.
fn chunked_hash<let N: u32, let M: u32>(kind: Field, address: Field, context: [u8; N]) -> Field {
    let mut inputs: [Field; HEADER_INPUTS + M] = [0; HEADER_INPUTS + M];
    inputs[0] = CARRIER_CONTEXT_DOMAIN;
    inputs[1] = kind;
    inputs[2] = address;
    inputs[3] = N as Field;
    for i in 0..N {
        let slot = HEADER_INPUTS + i / BYTES_PER_CHUNK;
        inputs[slot] = inputs[slot] * 256 + context[i] as Field;
    }
    pcash_hash(inputs)
}

mod tests {
    use crate::generated::pcash_constants::CARRIER_CONTEXT_DOMAIN;
    use crate::primitives::hash::pcash_hash;
    use super::{carrier_context_hash, CARRIER_KIND_EVENT, CARRIER_KIND_INBOX};

    global ADDRESS: Field = 0x3333333333333333333333333333333333333333;

    // N bytes of a counting pattern.
    fn pattern<let N: u32>() -> [u8; N] {
        let mut context: [u8; N] = [0; N];
        for i in 0..N {
            context[i] = (i + 1) as u8;
        }
        context
    }

    // The eight chunks of the 128-byte pattern, written without the helper.
    fn pattern_chunks() -> [Field; 8] {
        let context: [u8; 128] = pattern();
        let mut chunks: [Field; 8] = [0; 8];
        for chunk in 0..8 {
            for j in 0..16 {
                chunks[chunk] = chunks[chunk] * 256 + context[chunk * 16 + j] as Field;
            }
        }
        chunks
    }

    #[test]
    fn test_kinds_are_numbered() {
        assert_eq(CARRIER_KIND_INBOX, 0);
        assert_eq(CARRIER_KIND_EVENT, 1);
    }

    #[test]
    fn test_eight_chunk_context_is_the_plain_sponge() {
        let chunks = pattern_chunks();
        let expected = pcash_hash([
            CARRIER_CONTEXT_DOMAIN,
            CARRIER_KIND_EVENT,
            ADDRESS,
            128,
            chunks[0],
            chunks[1],
            chunks[2],
            chunks[3],
            chunks[4],
            chunks[5],
            chunks[6],
            chunks[7],
        ]);
        assert_eq(carrier_context_hash(CARRIER_KIND_EVENT, ADDRESS, pattern::<128>()), expected);
    }

    // An empty context still carries the eight zero chunk slots.
    #[test]
    fn test_empty_context_pads_to_eight_chunks() {
        let empty: [u8; 0] = [];
        let expected = pcash_hash([
            CARRIER_CONTEXT_DOMAIN,
            CARRIER_KIND_INBOX,
            ADDRESS,
            0,
            0,
            0,
            0,
            0,
            0,
            0,
            0,
            0,
        ]);
        assert_eq(carrier_context_hash(CARRIER_KIND_INBOX, ADDRESS, empty), expected);
    }

    // The last chunk is the integer of its own bytes, so a 17-byte context ends
    // in a one-byte chunk, and the eight-chunk minimum pads with zeros.
    #[test]
    fn test_short_final_chunk_is_not_shifted() {
        let mut chunks: [Field; 8] = [0; 8];
        for j in 0..16 {
            chunks[0] = chunks[0] * 256 + (j + 1) as Field;
        }
        chunks[1] = 17;
        let expected = pcash_hash([
            CARRIER_CONTEXT_DOMAIN,
            CARRIER_KIND_INBOX,
            ADDRESS,
            17,
            chunks[0],
            chunks[1],
            0,
            0,
            0,
            0,
            0,
            0,
        ]);
        assert_eq(carrier_context_hash(CARRIER_KIND_INBOX, ADDRESS, pattern::<17>()), expected);
    }

    // Past eight chunks every chunk takes a slot: a 129-byte context ends in a
    // ninth, one-byte chunk.
    #[test]
    fn test_context_beyond_eight_chunks_uses_every_chunk() {
        let chunks = pattern_chunks();
        let expected = pcash_hash([
            CARRIER_CONTEXT_DOMAIN,
            CARRIER_KIND_EVENT,
            ADDRESS,
            129,
            chunks[0],
            chunks[1],
            chunks[2],
            chunks[3],
            chunks[4],
            chunks[5],
            chunks[6],
            chunks[7],
            129,
        ]);
        assert_eq(carrier_context_hash(CARRIER_KIND_EVENT, ADDRESS, pattern::<129>()), expected);
    }

    #[test]
    fn test_kind_and_address_separate_carriers() {
        let empty: [u8; 0] = [];
        let inbox = carrier_context_hash(CARRIER_KIND_INBOX, ADDRESS, empty);
        assert(inbox != carrier_context_hash(CARRIER_KIND_EVENT, ADDRESS, empty));
        assert(inbox != carrier_context_hash(CARRIER_KIND_INBOX, ADDRESS + 1, empty));
    }

    #[test]
    fn test_length_separates_trailing_zero_bytes() {
        let mut longer: [u8; 17] = [0; 17];
        let context: [u8; 16] = pattern();
        for i in 0..16 {
            longer[i] = context[i];
        }
        assert(
            carrier_context_hash(CARRIER_KIND_EVENT, ADDRESS, context)
                != carrier_context_hash(CARRIER_KIND_EVENT, ADDRESS, longer),
        );
    }
}

// The L1 origin tree, and the proof-friendly normalization of canonical
// Ethereum logs into fixed-field leaves committed under each L1 origin leaf.

use crate::generated::pcash_constants::{L1_LOG_DOMAIN, L1_ORIGIN_DOMAIN};
use crate::primitives::hash::pcash_hash;
use crate::primitives::params::{
    BLOCK_HEADER_TREE_DEPTH, L1_LOG_TREE_DEPTH, L1_ORIGIN_INTEGER_BITS, L1_ORIGIN_TREE_DEPTH,
};
use crate::state::block::{block_header_fact, BLOCK_HEADER_KEY_L1_ORIGIN_ROOT};
use crate::state::merkle::binary_root_from_index;

pub struct L1LogGrounding {
    pub l1_origin_root_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    pub l1_block_number: Field,
    pub l1_block_hash_high: Field,
    pub l1_block_hash_low: Field,
    pub l1_block_timestamp: Field,
    pub l1_origin_index: Field,
    pub l1_origin_siblings: [Field; L1_ORIGIN_TREE_DEPTH],
    pub log_count: Field,
    pub log_leaf_index: Field,
    pub log_siblings: [Field; L1_LOG_TREE_DEPTH],
    pub transaction_index: Field,
    pub log_index: Field,
}

pub fn split_bytes32_128(value: [u8; 32]) -> (Field, Field) {
    let mut high: Field = 0;
    let mut low: Field = 0;
    for i in 0..16 {
        high = high * 256 + (value[i] as Field);
        low = low * 256 + (value[i + 16] as Field);
    }
    (high, low)
}

// One sponge over the log's fields. Topics are padded to four and split into
// big-endian 128-bit halves; data is split into 16-byte big-endian chunks and
// zero-padded to eight. This form covers logs with at most 128 data bytes.
// Membership under the node's logs root binds every hashed value, so callers
// open the leaf with `assert_normalized_log`.
pub fn normalized_log_leaf(
    transaction_index: Field,
    log_index: Field,
    emitter: Field,
    topic_count: Field,
    topic_limbs: [Field; 8],
    data_length: Field,
    data_limbs: [Field; 8],
) -> Field {
    pcash_hash([
        L1_LOG_DOMAIN,
        transaction_index,
        log_index,
        emitter,
        topic_count,
        topic_limbs[0],
        topic_limbs[1],
        topic_limbs[2],
        topic_limbs[3],
        topic_limbs[4],
        topic_limbs[5],
        topic_limbs[6],
        topic_limbs[7],
        data_length,
        data_limbs[0],
        data_limbs[1],
        data_limbs[2],
        data_limbs[3],
        data_limbs[4],
        data_limbs[5],
        data_limbs[6],
        data_limbs[7],
    ])
}

// The Ethereum block hash enters as its big-endian 128-bit halves.
pub fn l1_origin_leaf(
    block_number: Field,
    block_hash_high: Field,
    block_hash_low: Field,
    timestamp: Field,
    logs_root: Field,
    log_count: Field,
) -> Field {
    block_number.assert_max_bit_size::<L1_ORIGIN_INTEGER_BITS>();
    timestamp.assert_max_bit_size::<L1_ORIGIN_INTEGER_BITS>();
    log_count.assert_max_bit_size::<L1_ORIGIN_INTEGER_BITS>();
    pcash_hash([
        L1_ORIGIN_DOMAIN,
        block_number,
        block_hash_high,
        block_hash_low,
        timestamp,
        logs_root,
        log_count,
    ])
}

// Opens the log leaf up to the recent block's header: the log tree's root
// enters its L1 block's origin leaf, that leaf's path gives the L1 origin root,
// and the header must commit that root.
pub fn assert_normalized_log(
    recent_pcash_block_hash: Field,
    grounding: L1LogGrounding,
    log_leaf: Field,
) {
    assert(
        (grounding.log_leaf_index as u64) < (grounding.log_count as u64),
        "L1 log index must be below the log count",
    );
    let logs_root =
        binary_root_from_index(log_leaf, grounding.log_leaf_index, grounding.log_siblings);
    let block_leaf = l1_origin_leaf(
        grounding.l1_block_number,
        grounding.l1_block_hash_high,
        grounding.l1_block_hash_low,
        grounding.l1_block_timestamp,
        logs_root,
        grounding.log_count,
    );
    let l1_origin_root = binary_root_from_index(
        block_leaf,
        grounding.l1_origin_index,
        grounding.l1_origin_siblings,
    );
    block_header_fact(
        recent_pcash_block_hash,
        BLOCK_HEADER_KEY_L1_ORIGIN_ROOT,
        l1_origin_root,
        grounding.l1_origin_root_siblings,
    );
}

mod tests {
