// Result openings share the recent header's authenticated history root.
use crate::generated::pcash_constants::{
    PAYOUT_RESULT_DOMAIN, TRANSACTION_RESULT_DOMAIN, TRANSACTION_RESULTS_ROOT_DOMAIN,
    TRANSACTION_STATEMENT_DOMAIN,
};
use crate::primitives::hash::pcash_hash;
use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, HISTORY_TREE_DEPTH};
use crate::state::block::{
    block_hash_from_opening, BLOCK_HEADER_KEY_TRANSACTION_RESULTS_ROOT, history_fact,
};
use crate::state::merkle::binary_root_from_index;

global RESULT_TREE_DEPTH: u32 = 64;

pub struct ResultOpening {
    pub block_number: Field,
    pub history_siblings: [Field; HISTORY_TREE_DEPTH],
    pub results_header_siblings: [Field; BLOCK_HEADER_TREE_DEPTH],
    pub transaction_count: u64,
    pub payout_count: u64,
    pub result_index: u64,
    pub result_siblings: [Field; RESULT_TREE_DEPTH],
}

pub struct TransactionResult {
    pub tx_type: Field,
    pub funding_mode: Field,
    pub l1_transaction_index: Field,
    pub batch_item_index: Field,
    pub outcome: Field,
    pub poster_owner_commitment: Field,
    pub output_start_index: Field,
    pub statement_hash: Field,
}

pub struct PayoutResult {
    pub output_index: Field,
    pub owner_commitment: Field,
    pub open_fee_amount: Field,
    pub issuance_amount: Field,
}

pub fn statement_hash<let N: u32>(statement: [Field; N]) -> Field {
    let mut words = [0; N + 1];
    words[0] = TRANSACTION_STATEMENT_DOMAIN;
    for i in 0..N {
        words[i + 1] = statement[i];
    }
    pcash_hash(words)
}

pub fn transaction_result_leaf(result: TransactionResult) -> Field {
    pcash_hash([
        TRANSACTION_RESULT_DOMAIN,
        result.tx_type,
        result.funding_mode,
        result.l1_transaction_index,
        result.batch_item_index,
        result.outcome,
        result.poster_owner_commitment,
        result.output_start_index,
        result.statement_hash,
    ])
}

pub fn payout_result_leaf(result: PayoutResult) -> Field {
    pcash_hash([
        PAYOUT_RESULT_DOMAIN,
        result.output_index,
        result.owner_commitment,
        result.open_fee_amount,
        result.issuance_amount,
    ])
}

// Opens the result leaf up to its block: the result tree's root gives the
// block's transaction results root, whose header path gives the block hash.
// That block is the recent block, or one the recent history root commits.
pub fn assert_result(
    recent_pcash_block_hash: Field,
    history_root: Field,
    opening: ResultOpening,
    leaf: Field,
    is_payout: bool,
) {
    if is_payout {
        assert(
            opening.result_index >= opening.transaction_count,
            "payout result must follow the transactions",
        );
        assert(
            opening.result_index - opening.transaction_count < opening.payout_count,
            "payout result index must be in range",
        );
    } else {
        assert(
            opening.result_index < opening.transaction_count,
            "transaction result index must be in range",
        );
    }
    let root = binary_root_from_index(leaf, opening.result_index as Field, opening.result_siblings);
    let results_root = pcash_hash([
        TRANSACTION_RESULTS_ROOT_DOMAIN,
        opening.transaction_count as Field,
        opening.payout_count as Field,
        root,
    ]);
    let block_hash = block_hash_from_opening(
        results_root,
        BLOCK_HEADER_KEY_TRANSACTION_RESULTS_ROOT,
        opening.results_header_siblings,
    );
    if block_hash != recent_pcash_block_hash {
        history_fact(
            history_root,
            opening.block_number,
            block_hash,
            opening.history_siblings,
        );
    }
}

mod tests {
    use crate::generated::pcash_constants::TRANSACTION_RESULTS_ROOT_DOMAIN;
    use crate::primitives::hash::pcash_hash;
    use crate::primitives::params::{BLOCK_HEADER_TREE_DEPTH, HISTORY_TREE_DEPTH};
    use crate::state::block::{
        block_hash_from_opening, BLOCK_HEADER_KEY_TRANSACTION_RESULTS_ROOT, history_leaf,
    };
    use crate::state::merkle::binary_root_from_index;
    use super::{assert_result, RESULT_TREE_DEPTH, ResultOpening};

    global LEAF: Field = 0x1eaf;

    // Transaction result 1 of a block with 3 transactions and 2 payouts, at
    // block number 9. Returns its opening, the block's hash, and a history root
    // that commits the block.
    fn result_fixture() -> (ResultOpening, Field, Field) {
        let mut result_siblings = [0; RESULT_TREE_DEPTH];
        result_siblings[0] = 0x51;
        result_siblings[5] = 0x52;
        let root = binary_root_from_index(LEAF, 1, result_siblings);
        let results_root = pcash_hash([TRANSACTION_RESULTS_ROOT_DOMAIN, 3, 2, root]);
        let header_siblings: [Field; BLOCK_HEADER_TREE_DEPTH] = [0x61, 0x62, 0x63, 0x64];
        let block_hash = block_hash_from_opening(
            results_root,
            BLOCK_HEADER_KEY_TRANSACTION_RESULTS_ROOT,
            header_siblings,
        );
        let mut history_siblings = [0; HISTORY_TREE_DEPTH];
        history_siblings[2] = 0x71;
        let history_root = binary_root_from_index(history_leaf(block_hash), 9, history_siblings);
        let opening = ResultOpening {
            block_number: 9,
            history_siblings,
            results_header_siblings: header_siblings,
            transaction_count: 3,
            payout_count: 2,
            result_index: 1,
            result_siblings,
        };
        (opening, block_hash, history_root)
    }

    // The recent block's header opens the result, so no history opening runs.
    #[test]
    fn test_result_in_the_recent_block_needs_no_history() {
        let (opening, block_hash, _) = result_fixture();
        assert_result(block_hash, 0xdead, opening, LEAF, false);
    }

    #[test]
    fn test_result_in_an_earlier_block_opens_under_history() {
        let (opening, _, history_root) = result_fixture();
        assert_result(0xbeef, history_root, opening, LEAF, false);
    }

    #[test(should_fail_with = "block hash must be in the PCASH history tree")]
    fn test_result_in_an_earlier_block_rejects_another_history_root() {
        let (opening, _, history_root) = result_fixture();
        assert_result(0xbeef, history_root + 1, opening, LEAF, false);
    }

    // Every opening below the header moves the block hash off the recent block,
    // so the result must then open under history, which commits only the
    // genuine block.
    #[test(should_fail_with = "block hash must be in the PCASH history tree")]
    fn test_result_rejects_another_leaf() {
        let (opening, block_hash, history_root) = result_fixture();
        assert_result(block_hash, history_root, opening, LEAF + 1, false);
    }

    #[test(should_fail_with = "block hash must be in the PCASH history tree")]
    fn test_result_rejects_another_result_sibling() {
        let (mut opening, block_hash, history_root) = result_fixture();
        opening.result_siblings[5] = 0x53;
        assert_result(block_hash, history_root, opening, LEAF, false);
    }

    #[test(should_fail_with = "block hash must be in the PCASH history tree")]
    fn test_result_rejects_another_payout_count() {
        let (mut opening, block_hash, history_root) = result_fixture();
        opening.payout_count = 3;
        assert_result(block_hash, history_root, opening, LEAF, false);
    }

    #[test(should_fail_with = "block hash must be in the PCASH history tree")]
    fn test_result_rejects_another_header_sibling() {
        let (mut opening, block_hash, history_root) = result_fixture();
        opening.results_header_siblings[BLOCK_HEADER_TREE_DEPTH - 1] = 0x65;
        assert_result(block_hash, history_root, opening, LEAF, false);
    }

    #[test(should_fail_with = "transaction result index must be in range")]
    fn test_transaction_result_rejects_an_index_past_the_transactions() {
        let (mut opening, block_hash, history_root) = result_fixture();
        opening.transaction_count = 1;
        assert_result(block_hash, history_root, opening, LEAF, false);
    }

    #[test(should_fail_with = "payout result must follow the transactions")]
    fn test_payout_result_rejects_a_transaction_index() {
        let (opening, block_hash, history_root) = result_fixture();
        assert_result(block_hash, history_root, opening, LEAF, true);
    }
}

// The configuration of the asset covenant fixture: the one live contract
// account its asset value may move to, and the largest open fee it may pay.

use crate::generated::reference_rule_constants::REFERENCE_ASSET_CONFIGURATION_DOMAIN;
use pcash_protocol::primitives::hash::pcash_hash;
use pcash_protocol::primitives::range::assert_amount;

// The covenant's sub-tag under REFERENCE_ASSET_CONFIGURATION_DOMAIN. The shared
// asset claim fixture uses 4 to 6.
pub global ASSET_COVENANT_SUCCESSOR_TAG: Field = 3;

pub fn asset_covenant_successor_configuration_commitment(
    max_native_open_fee_amount: Field,
    successor_address: Field,
    successor_nullifier_key_commitment: Field,
    successor_rule_set_commitment: Field,
    successor_account_revision: Field,
    successor_receive_key_hash: Field,
) -> Field {
    assert_amount(max_native_open_fee_amount);
    // The covenant opens the successor fields from the live account leaf.
    pcash_hash([
        REFERENCE_ASSET_CONFIGURATION_DOMAIN,
        ASSET_COVENANT_SUCCESSOR_TAG,
        max_native_open_fee_amount,
        successor_address,
        successor_nullifier_key_commitment,
        successor_rule_set_commitment,
        successor_account_revision,
        successor_receive_key_hash,
    ])
}

mod tests {
    use super::asset_covenant_successor_configuration_commitment;

    #[test]
    fn test_covenant_successor_configuration_binds_the_complete_account() {
        let base =
            asset_covenant_successor_configuration_commitment(5, 0x1234, 0x2345, 0x3456, 1, 0);
        assert(
            base
                != asset_covenant_successor_configuration_commitment(
                    5,
                    0x1234,
                    0x2345,
                    0x3457,
                    1,
                    0,
                ),
        );
        assert(
            base
                != asset_covenant_successor_configuration_commitment(
                    6,
                    0x1234,
                    0x2345,
                    0x3456,
                    1,
                    0,
                ),
        );
    }

    // Zero fields are hash inputs like any other. Whether they describe a live
    // successor is the covenant's account-leaf opening, not this commitment.
    #[test]
    fn test_covenant_successor_configuration_hashes_zero_fields() {
        let zero = asset_covenant_successor_configuration_commitment(5, 0, 0, 0, 0, 0);
        assert(zero != asset_covenant_successor_configuration_commitment(5, 0x1234, 0, 0, 0, 0));
        assert(zero != asset_covenant_successor_configuration_commitment(5, 0, 0, 0, 1, 0));
    }
}

// Readable one-shot asset creation authorized by the registered owner.
//
// The signer approves the asset's identity (metadata, initial supply and
// asset secret commitment) and the asset ID they derive, every directed
// output, the fee, the transaction context and the validity window. Every
// undirected real output is owner change. The rule returns the asset-creation
// action for that asset ID, which only the asset-creation kernel accepts, and
// only for the asset it derives; that kernel also binds the single creation
// marker to the asset ID.

use crate::configuration::Configuration;
use crate::message::verify_value_message;
use crate::owner::open_owner;
use crate::value_rule::{assert_output_declarations, assert_relay_terms, OutputDeclaration};
use pcash_protocol::authorization::statement::{
    asset_creation_action_commitment, rule_statement, RULE_STATEMENT_LENGTH,
};
use pcash_protocol::ledger::asset::standard_fungible_asset_id;
use pcash_protocol::ledger::private_value::{
    private_value_commitment, PrivateValue, SLOT_CLASS_ASSET_CREATION, SLOT_CLASS_DUMMY,
    SLOT_CLASS_NATIVE,
};
use signature_common::secp256k1::{Secp256k1PubKey, Signature};

// Returns the rule statement and the asset ID the signed asset fields derive.
pub fn asset_creation_relation<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    configuration: Configuration,
    signer_address: Field,
    nk_root: Field,
    metadata_commitment: Field,
    initial_supply: Field,
    asset_secret_commitment: Field,
    outputs: [OutputDeclaration; N_OUT],
    relay_fee_amount: Field,
    relay_fee_owner_commitment: Field,
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    output_note_secrets: [Field; N_OUT],
    owner_change_amounts: [Field; N_OUT],
    event_entry: Field,
) -> ([Field; RULE_STATEMENT_LENGTH], Field) {
    let owner = open_owner(signer_address, nk_root, configuration);
    let asset_id =
        standard_fungible_asset_id(metadata_commitment, initial_supply, asset_secret_commitment);
    // The asset-creation kernel requires the one creation marker and binds it
    // to the asset ID; it also admits application markers, which this message
    // cannot describe. Every ASSET output body is bound to this rule's asset ID.
    for i in 0..N_IN {
        let class = private_value.input_slot_classes[i];
        assert(
            (class == SLOT_CLASS_NATIVE)
                | (class == SLOT_CLASS_DUMMY)
                | (class == SLOT_CLASS_ASSET_CREATION),
            "creation input must be native, dummy or the creation marker",
        );
    }
    assert_relay_terms(private_value, relay_fee_amount, relay_fee_owner_commitment);
    let _ = assert_output_declarations(
        private_value,
        signer_address,
        nk_root,
        asset_id,
        outputs,
        relay_fee_amount,
        relay_fee_owner_commitment,
        output_note_secrets,
        owner_change_amounts,
    );
    let statement = rule_statement(
        owner.authorization_commitment,
        asset_creation_action_commitment(
            pcash_chain_id,
            private_value_commitment(private_value),
            asset_id,
        ),
        recent_pcash_block_hash,
        event_entry,
    );
    (statement, asset_id)
}

pub fn authorize<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    type_hash: [u8; 32],
    pcash_chain_id: Field,
    recent_pcash_block_hash: Field,
    configuration: Configuration,
    signature: Signature,
    pubkey: Secp256k1PubKey,
    nk_root: Field,
    metadata_commitment: Field,
    initial_supply: Field,
    asset_secret_commitment: Field,
    outputs: [OutputDeclaration; N_OUT],
    issuance_recipient: Field,
    relay_fee_amount: Field,
    relay_fee_owner_commitment: Field,
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    issuance_note_secret: Field,
    output_note_secrets: [Field; N_OUT],
    owner_change_amounts: [Field; N_OUT],
    event_entry: Field,
) -> [Field; RULE_STATEMENT_LENGTH] {
    let signer_address = pubkey.ethereum_address();
    let (statement, asset_id) = asset_creation_relation(
        pcash_chain_id,
        recent_pcash_block_hash,
        configuration,
        signer_address,
        nk_root,
        metadata_commitment,
        initial_supply,
        asset_secret_commitment,
        outputs,
        relay_fee_amount,
        relay_fee_owner_commitment,
        private_value,
        output_note_secrets,
        owner_change_amounts,
        event_entry,
    );
    verify_value_message(
        signature,
        pubkey,
        signer_address,
        configuration,
        type_hash,
        pcash_chain_id,
        nk_root,
        [asset_id, metadata_commitment, initial_supply, asset_secret_commitment],
        outputs,
        private_value,
        issuance_recipient,
        issuance_note_secret,
        relay_fee_amount,
        relay_fee_owner_commitment,
    );
    statement
}

