// The signed message of the reference value rules: the PCASH chain ID, the
// rule's own fields, each declared output as (recipient, amount, asset_id), and
// eight fields every value message ends with: the open fee, the issuance route,
// the relay terms, the transaction context and the validity window.
//
// The chain ID is the same witness the rule hashes into its action commitment,
// so a signature approves an action on one chain only.

use crate::configuration::Configuration;
use crate::issuance_opening::assert_owner_issuance_opening;
use crate::payout::transaction_context;
use crate::value_rule::OutputDeclaration;
use pcash_protocol::ledger::private_value::PrivateValue;
use signature_common::secp256k1::{Secp256k1PubKey, Signature};

// The owner's approval of a value message: the issuance route it names opens
// as the owner directed, and the signer signed the message. Both bind the
// transaction context the chain ID and the private value's nullifiers derive.
// `signer_address` is the address of `pubkey`, which the caller's relation
// also reads.
pub fn verify_value_message<let P: u32, let D: u32, let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    signature: Signature,
    pubkey: Secp256k1PubKey,
    signer_address: Field,
    configuration: Configuration,
    type_hash: [u8; 32],
    pcash_chain_id: Field,
    nk_root: Field,
    fields: [Field; P],
    outputs: [OutputDeclaration; D],
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    issuance_recipient: Field,
    issuance_note_secret: Field,
    relay_fee_amount: Field,
    relay_fee_owner_commitment: Field,
) {
    let context =
        transaction_context::<N_IN, N_OUT, SHAPE>(pcash_chain_id, private_value.nullifiers);
    assert_owner_issuance_opening(
        private_value,
        context,
        signer_address,
        nk_root,
        issuance_recipient,
        issuance_note_secret,
    );
    signature.verify(
        configuration.signing_hash(
            type_hash,
            value_message(
                pcash_chain_id,
                fields,
                outputs,
                private_value,
                issuance_recipient,
                relay_fee_amount,
                relay_fee_owner_commitment,
                context,
            ),
        ),
        pubkey,
    );
}

fn value_message<let P: u32, let D: u32, let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    fields: [Field; P],
    outputs: [OutputDeclaration; D],
    private_value: PrivateValue<N_IN, N_OUT, SHAPE>,
    issuance_recipient: Field,
    relay_fee_amount: Field,
    relay_fee_owner_commitment: Field,
    context: Field,
) -> [Field; 1 + P + 3 * D + 8] {
    let mut message = [0; 1 + P + 3 * D + 8];
    message[0] = pcash_chain_id;
    for i in 0..P {
        message[1 + i] = fields[i];
    }
    for i in 0..D {
        message[1 + P + 3 * i] = outputs[i].recipient;
        message[2 + P + 3 * i] = outputs[i].amount;
        message[3 + P + 3 * i] = outputs[i].asset_id;
    }
    let terms = [
        private_value.open_fee_amount,
        issuance_recipient,
        private_value.issuance_owner_commitment,
        relay_fee_amount,
        relay_fee_owner_commitment,
        context,
        private_value.not_before_timestamp,
        private_value.valid_until_timestamp,
    ];
    for i in 0..8 {
        message[1 + P + 3 * D + i] = terms[i];
    }
    message
}

// The owner binding of the readable owner-only rules.
//
// Identity comes from the public key the signature verifies under, never from
// a witnessed address or a configured delegate. The rule's authorization
// commitment names that key's address and this rule's configuration opened
// with the rule's own `nk_root`. The kernel compares it with the account's
// address and installed configuration, so a key that does not own the account
// cannot produce it, and a builder cannot substitute another root for the one
// the rule derives owner change and self-issuance secrets from.

use crate::configuration::{Configuration, configuration_commitment};
use pcash_protocol::authorization::statement::authorization_commitment;
use pcash_protocol::ledger::note::nullifier_key_commitment;

pub struct OwnerOpening {
    pub nullifier_key_commitment: Field,
    pub authorization_commitment: Field,
}

pub fn open_owner(
    signer_address: Field,
    nk_root: Field,
    configuration: Configuration,
) -> OwnerOpening {
    let nullifier_key_commitment = nullifier_key_commitment(nk_root);
    OwnerOpening {
        nullifier_key_commitment,
        authorization_commitment: authorization_commitment(
            signer_address,
            configuration_commitment(configuration, nullifier_key_commitment),
        ),
    }
}

// Recoverable ownership (spec Appendix B): payout note secrets for system
// payouts and deterministic output note secrets. These are wallet conventions,
// not consensus; no kernel calls them.

use pcash_protocol::generated::pcash_constants::{
    IMPLICIT_NOTE_SECRET_SEED_DOMAIN, PAYOUT_NOTE_SECRET_DOMAIN, PAYOUT_SEED_DOMAIN,
    PAYOUT_TX_CONTEXT_DOMAIN, TRANSACT_NOTE_SECRET_DOMAIN,
};
use pcash_protocol::ledger::note::note_nk;
use pcash_protocol::primitives::hash::pcash_hash;

pub global ISSUANCE_ROLE: Field = 3;

pub fn payout_seed(nk_root: Field) -> Field {
    pcash_hash([PAYOUT_SEED_DOMAIN, note_nk(nk_root)])
}

pub fn transaction_context<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    pcash_chain_id: Field,
    nullifiers: [Field; N_IN],
) -> Field {
    let mut operands = [0; N_IN + 5];
    operands[0] = PAYOUT_TX_CONTEXT_DOMAIN;
    operands[1] = pcash_chain_id;
    operands[2] = SHAPE as Field;
    operands[3] = N_IN as Field;
    operands[4] = N_OUT as Field;
    for i in 0..N_IN {
        operands[5 + i] = nullifiers[i];
    }
    pcash_hash(operands)
}

pub fn payout_note_secret(seed: Field, role: Field, context: Field) -> Field {
    pcash_hash([PAYOUT_NOTE_SECRET_DOMAIN, seed, role, context])
}

// noteSecretSeed = poseidon(IMPLICIT_NOTE_SECRET_SEED_DOMAIN, nk).
pub fn note_secret_seed(nk: Field) -> Field {
    pcash_hash([IMPLICIT_NOTE_SECRET_SEED_DOMAIN, nk])
}

// noteSecret_i = poseidon(TRANSACT_NOTE_SECRET_DOMAIN, noteSecretSeed,
//                         SHAPE, N_IN, N_OUT, nullifier_0, ..., nullifier_(N_IN-1), i,
//                         outputEntropy_i).
// The complete ordered published nullifiers make the salt unique per accepted transaction
// and independent of output-slot arrangement; they are fixed before any output
// is constructed, so there is no derivation cycle.
// `outputEntropy_i` is a private witness this derivation does not constrain;
// its caller fixes it. Owner change passes 0, so the owner recomputes the
// secret from its key and the published nullifiers. The wallet chooses the
// entropy of every other output it creates.
pub fn note_secret<let N_IN: u32, let N_OUT: u32, let SHAPE: u32>(
    seed: Field,
    nullifiers: [Field; N_IN],
    i: Field,
    output_entropy: Field,
) -> Field {
    let mut operands = [0; N_IN + 7];
    operands[0] = TRANSACT_NOTE_SECRET_DOMAIN;
    operands[1] = seed;
    operands[2] = SHAPE as Field;
    operands[3] = N_IN as Field;
    operands[4] = N_OUT as Field;
    for j in 0..N_IN {
        operands[5 + j] = nullifiers[j];
    }
    operands[5 + N_IN] = i;
    operands[6 + N_IN] = output_entropy;
    let derived = pcash_hash(operands);
    derived
}

mod tests {
    use super::{note_secret, note_secret_seed, payout_seed, transaction_context};
    use pcash_protocol::generated::pcash_constants::{
        IMPLICIT_NOTE_SECRET_SEED_DOMAIN, PAYOUT_SEED_DOMAIN, PAYOUT_TX_CONTEXT_DOMAIN,
        TRANSACT_NOTE_SECRET_DOMAIN,
    };
    use pcash_protocol::ledger::note::note_nk;
    use pcash_protocol::primitives::hash::pcash_hash;

    #[test]
    fn test_payout_seed_and_transaction_context() {
        let seed = payout_seed(0x1234);
        let context = transaction_context::<4, 5, 0>(1, [11, 12, 13, 14]);
        assert(seed == pcash_hash([PAYOUT_SEED_DOMAIN, note_nk(0x1234)]));
        assert(context == pcash_hash([PAYOUT_TX_CONTEXT_DOMAIN, 1, 0, 4, 5, 11, 12, 13, 14]));
        assert(context != transaction_context::<4, 5, 0>(2, [11, 12, 13, 14]));
        assert(context != transaction_context::<4, 5, 0>(1, [11, 12, 13, 15]));
        assert(context != transaction_context::<4, 5, 0>(1, [12, 11, 13, 14]));
    }

    #[test]
    fn test_note_secret_derivation() {
        let nk = note_nk(0x9999);
        let seed = note_secret_seed(nk);
        assert(seed == pcash_hash([IMPLICIT_NOTE_SECRET_SEED_DOMAIN, nk]));
        let nullifiers = [0x1a, 0x2b, 0x3c, 0x4d];
        let s0 = note_secret::<4, 5, 0>(seed, nullifiers, 0, 0);
        let s1 = note_secret::<4, 5, 0>(seed, nullifiers, 1, 0);
        assert(
            s0
                == pcash_hash([
                    TRANSACT_NOTE_SECRET_DOMAIN,
                    seed,
                    0,
                    4,
                    5,
                    0x1a,
                    0x2b,
                    0x3c,
                    0x4d,
                    0,
                    0,
                ]),
        );
        assert(s0 != s1);
        // Distinct entropy in the same slot yields a distinct secret.
        assert(s0 != note_secret::<4, 5, 0>(seed, nullifiers, 0, 0xf00d));
        // The salt is the published nullifiers: changing one changes the secret.
        assert(s0 != note_secret::<4, 5, 0>(seed, [0x1a, 0x2b, 0x3c, 0x4e], 0, 0));
    }
}

